INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p7-1', 'doc-11-oasis-taxii21', '', 7, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 7 of 79 1 Introduction TAXII is an application layer protocol for the communication of cyber threat information in a simple and scalable manner. This specification defines the TAXII RESTful API and its resources along with the requirements for TAXII Client and Server implementations.', 'kb-doc-11-oasis-taxii21-p7-1', 0, 61, '11-oasis-taxii21', 'retrieved', '9D02F42BCC485BB61330DE342CD23998186AC931904DF28F5274E134FA0F0C2F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
