INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p7-2', 'doc-11-oasis-taxii21', '', 7, '1.1 IPR Policy This specification is provided under the Non-Assertion Mode of the OASIS IPR Policy, the mode chosen when the Technical Committee was established. For information on whether any patents have been disclosed that may be essential to implementing this specification, and any offers of patent licensing terms, please refer to the Intellectual Property Rights section of the TC’s web page ( https://www.oasis- open.org/committees/cti/ipr.php).', 'kb-doc-11-oasis-taxii21-p7-2', 0, 65, '11-oasis-taxii21', 'retrieved', '9E33470D4CB813D4F8BB8E7FED84146312E69F61AC94487917D15C932DDF0244', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
