INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p10-5', 'doc-11-oasis-taxii21', '', 10, '1.5 Document Conventions 1.5.1 Naming Conventions All type names, property names and literals are in lowercase. Words in property names are separated with an underscore (_), while words in type names and string enumerations are separated with a hyphen (Unicode hyphen-minus, U+002D, ‘-‘). All type names, property names, object names, and vocabulary terms are between three and 250 characters long.', 'kb-doc-11-oasis-taxii21-p10-5', 0, 60, '11-oasis-taxii21', 'retrieved', '3B711C96CEDF471BBF6771E0A22A432FAD6F3A92EDA4B871DFAC0A24CEEDC6E3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p10-6', 'doc-11-oasis-taxii21', '', 10, '1.5.2 Font Colors and Style The following color, font and font style conventions are used in this document: ● The Consolas font is used for all type names, property names and literals.', 'kb-doc-11-oasis-taxii21-p10-6', 0, 32, '11-oasis-taxii21', 'retrieved', 'EBCA8D5E472AC4E13CF9E4BA2DE5B3B88CBE097C6FC063EA79FD5C02625FA82E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p10-7', 'doc-11-oasis-taxii21', '', 10, '○ resource and type names are in red with a light red background – collection ○ property names are in bold style – description ○ parameter names in URLs are stylized with angled brackets - {api-root} ○ literals (values) are in blue with a blue background – complete ● All examples in this document are expressed in Consolas 9-point font, with straight quotes, black text, 2-space indentation, and sometimes in a light grey background. JSON examples in this document are representations of JSON Objects. They should not be interpreted as string literals.', 'kb-doc-11-oasis-taxii21-p10-7', 0, 92, '11-oasis-taxii21', 'retrieved', '9BDD55E13C654CE6CC515A53F00DB568CE271FD77E6CAA09752E34D18D2AABD5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p10-8', 'doc-11-oasis-taxii21', '', 10, 'The ordering of object keys is insignificant. Whitespace before or after JSON structural characters in the examples are insignificant [RFC8259].', 'kb-doc-11-oasis-taxii21-p10-8', 0, 20, '11-oasis-taxii21', 'retrieved', '65029E71F1A925ACD2D5BD4C52CD1C100C3A6D077172A06515EEA46AAFA05A87', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p10-9', 'doc-11-oasis-taxii21', '', 10, '● Parts of the example may be omitted for conciseness and clarity. These omitted parts are denoted with ellipses (...).', 'kb-doc-11-oasis-taxii21-p10-9', 0, 20, '11-oasis-taxii21', 'retrieved', '37E443DCF0DF339FE43D0D8F42A8C2DB9C0FEEF913610C41012D394DEF24955D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p10-10', 'doc-11-oasis-taxii21', '', 10, '1.6 Overview Trusted Automated Exchange of Intelligence Information (TAXII) is an application layer protocol used to exchange cyber threat intelligence (CTI) over HTTPS. TAXII enables organizations to share CTI by defining an API that aligns with common sharing models. Specifically, TAXII defines two primary services, Collections and Channels, to support a variety of commonly-used sharing models. Collections allow a producer to host a set of CTI data that can be requested by consumers. Channels allow producers to push data to many consumers; and allow consumers to receive data from many producers. Collections and Channels can be organized by grouping them into an API Root to support the needs of a particular trust group or to organize them in some other way. Note: This version of the TAXII specification reserves the keywords required for Channels but does not specify Channel services. Channels and their services will be defined in a subsequent version of this specification.', 'kb-doc-11-oasis-taxii21-p10-10', 0, 154, '11-oasis-taxii21', 'retrieved', 'D62D239B1347DF0C976970EAA791DF3D4C857BF83AB191B41884649A09E496FD', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-1', 'doc-11-oasis-taxii21', '', 11, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 11 of 79 TAXII is specifically designed to support the exchange of CTI represented in STIX. As such, the examples and some features in the specification are intended to align with STIX. This does not mean TAXII cannot be used to share data in other formats; it is designed for STIX but is not limited to STIX.', 'kb-doc-11-oasis-taxii21-p11-1', 0, 74, '11-oasis-taxii21', 'retrieved', 'AC5FF92498BDEB04FFE3D42E158AD075D00C78422D9114CEEF7CBAEFE9F440C4', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-2', 'doc-11-oasis-taxii21', '', 11, '1.6.1 Discovery This specification defines two discovery methods. The first is a network level discovery that uses a DNS SRV record [RFC2782]. This DNS SRV record can be used to advertise the location of a TAXII Server within a network (e.g., so that TAXII-enabled security infrastructure can automatically locate an organization''s internal TAXII Server) or to the general Internet. See section 3.9 for complete information on advertising TAXII Servers in DNS.', 'kb-doc-11-oasis-taxii21-p11-2', 0, 71, '11-oasis-taxii21', 'retrieved', '9501A9E0EEFA33A625F3AB5584405BD6E58A546D528273744CD546063D0CC4BF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-3', 'doc-11-oasis-taxii21', '', 11, 'The second discovery method is a Discovery Endpoint (this specification uses the term Endpoint to identify a URL and an HTTP method with a defined request and response) that enables authorized clients to obtain information about a TAXII Server and get a list of API Roots. See section 4.1 for complete information on the Discovery Endpoint.', 'kb-doc-11-oasis-taxii21-p11-3', 0, 56, '11-oasis-taxii21', 'retrieved', '69DE5BC9FA7A15955AAE06BF3F73ECF17703EDD3D309423802107DA17EA1382E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-4', 'doc-11-oasis-taxii21', '', 11, '1.6.2 API Roots API Roots are logical groupings of TAXII Collections, Channels, and related functionality. A TAXII server instance can support one or more API Roots. API Roots can be thought of as instances of the TAXII API available at different URLs, where each API Root is the "root" URL of that particular instance of the TAXII API. Organizing the Collections and Channels into API Roots allows for a division of content and access control by trust group or any other logical grouping. For example, a single TAXII Server could h ost multiple API Roots - one API Root for Collections and Channels used by Sharing Group A and another API Root for Collections and Channels used by Sharing Group B.', 'kb-doc-11-oasis-taxii21-p11-4', 0, 121, '11-oasis-taxii21', 'retrieved', 'F2E62D13F39CB260EACE0D0FBD8AC965671FA9F5C7BF9467ECA34B5AE15A121D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-5', 'doc-11-oasis-taxii21', '', 11, 'Each API Root contains a set of Endpoints that a TAXII Client contacts in order to interac t with the TAXII Server. This interaction can take several forms: ● Server Discovery, as described above, can be used to learn about the API Roots hosted by a TAXII Server.', 'kb-doc-11-oasis-taxii21-p11-5', 0, 48, '11-oasis-taxii21', 'retrieved', '55DF3E4A60A1CA92C20E7C15C3F7BE8AED3B80D7324486F0374A99BE200D06B2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-6', 'doc-11-oasis-taxii21', '', 11, '● Each API Root might support zero or more Collections. Interactions with Collections i nclude discovering the type of CTI contained in that Collection, pushing new CTI to that Collection, and/or retrieving CTI from that Collection. Each piece of CTI content in a Collection is referred to as an Object.', 'kb-doc-11-oasis-taxii21-p11-6', 0, 50, '11-oasis-taxii21', 'retrieved', 'E89B4B5C1CCA929CF5646FD26E5AEA85937DCBC38EF035252F76447A20B1C55A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-8', 'doc-11-oasis-taxii21', '', 11, '● Each API Root also allows TAXII Clients to check on the Status of certain types of requests to the TAXII Server. For example, if a TAXII Client submitted new CTI, a Status request can allow the Client to check on whether the new CTI was accepted.', 'kb-doc-11-oasis-taxii21-p11-8', 0, 47, '11-oasis-taxii21', 'retrieved', '1729BFA2F050BB61A80F36A7DFBC54185FC25686C98E050D3A8CBFF34D2E807D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p11-10', 'doc-11-oasis-taxii21', '', 11, 'Example API Root URLs https://example.com/ https://api1.example.com/ https://example.com/api1/ https://example.com/api2/ https://example.org/trustgroup1/ https://example.org/taxii2/api1/', 'kb-doc-11-oasis-taxii21-p11-10', 0, 10, '11-oasis-taxii21', 'retrieved', '405DEF40D6CB297EB098EC3496F47A8410F75F522BF59554A4F9497A4A102481', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
