INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p13-2', 'doc-11-oasis-taxii21', '', 13, '1.6.6 Transport The TAXII protocol defined in this specification uses HTTPS (HTTP over TLS) as the transport for all communications.', 'kb-doc-11-oasis-taxii21-p13-2', 0, 20, '11-oasis-taxii21', 'retrieved', '49188A2B5412B7078EC3651BC5C9F395666A4EBD84DAFAAB2A3D8FF37A438DC7', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p13-3', 'doc-11-oasis-taxii21', '', 13, '1.6.7 Serialization This specification uses UTF-8 encoded JSON as defined in [RFC7493] and [RFC8259] for the serialization of all TAXII resources.', 'kb-doc-11-oasis-taxii21-p13-3', 0, 21, '11-oasis-taxii21', 'retrieved', 'D9AC181ABF4E3FA040A701B30AD080ACE259548F567DC5AF20ED3E19A378B9C3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p13-4', 'doc-11-oasis-taxii21', '', 13, '1.6.8 Content Negotiation This specification uses media types (section 3.1.1.1 of [RFC7231]) and an optional "version" parameter in the HTTP Accept header (section 5.3.2 of [RFC7231]) and Content-Type header (section 3.1.1.5 of [RFC7231]) to perform HTTP content negotiation as defined in [RFC7231]. It is important that TAXII Clients and Servers use correct Accept and Content-Type headers to negotiate TAXII versions.', 'kb-doc-11-oasis-taxii21-p13-4', 0, 60, '11-oasis-taxii21', 'retrieved', '03EC99061EAC212E6E2636D42742D8E064FAF56C28B36156DBB4C821754BA5FC', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p13-5', 'doc-11-oasis-taxii21', '', 13, '1.6.8.1 Media Types The TAXII media types used in this specification are summarized in the following table and are used for both requests and responses. Appendix B contains the official IANA registration information for the TAXII media type.', 'kb-doc-11-oasis-taxii21-p13-5', 0, 38, '11-oasis-taxii21', 'retrieved', 'D361F8A9BC599B5663B72E711545094F0606E545F2F3135F56D02A4659610DAA', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p13-7', 'doc-11-oasis-taxii21', '', 13, '1.6.8.2 Version Parameter This section defines the optional version parameter that can be used with content negotiation. The version parameter is defined per the guidelines in section 4.3 of [RFC6838] and the value is of the form ''n.m'', where n is the major version and m the minor version, both unsigned integer values.', 'kb-doc-11-oasis-taxii21-p13-7', 0, 53, '11-oasis-taxii21', 'retrieved', '7ED671B1270558574830FA2EB633B1E51F5A9C45D7805A68DF5BFA0FBFAD974B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p13-8', 'doc-11-oasis-taxii21', '', 13, 'The value for the version parameter that represents the final contents of this specification is "2.1".', 'kb-doc-11-oasis-taxii21-p13-8', 0, 16, '11-oasis-taxii21', 'retrieved', '4FACA00AA355C5883057A4A036639D6EB3D8300A5C865FF041722DD7DF63D0D5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-1', 'doc-11-oasis-taxii21', '', 14, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 14 of 79 Media Type with Optional Version Parameter Description application/taxii+json;version=2.1 TAXII version 2.1 in JSON application/taxii+json Latest version of TAXII that the server supports', 'kb-doc-11-oasis-taxii21-p14-1', 0, 42, '11-oasis-taxii21', 'retrieved', '0ADDCAB7306122109E818FED1D6D3635E4174A799669E737784FD9DE263FEA7D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
