INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-2', 'doc-11-oasis-taxii21', '', 14, '1.6.9 Authentication and Authorization Access control to an instance of the TAXII API is specific to the sharing community, vendor, or product and is not defined by this specification.', 'kb-doc-11-oasis-taxii21-p14-2', 0, 29, '11-oasis-taxii21', 'retrieved', '5DAABA105E12D63DFD563EB0561DCAA5F191B81D5D6AB0371DB92CCC9CCCABED', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-3', 'doc-11-oasis-taxii21', '', 14, 'Authentication and Authorization in TAXII is implemented as defined in [RFC7235], using the WWW- Authenticate and Authorization HTTP headers.', 'kb-doc-11-oasis-taxii21-p14-3', 0, 19, '11-oasis-taxii21', 'retrieved', 'D69F237CD687711C11725CBD7773C357BD9CA6EF7BBB98FC1ABF7E403DDE098C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-4', 'doc-11-oasis-taxii21', '', 14, 'HTTP Basic authentication, as defined in [RFC7617] is the suggested authentication scheme in TAXII. As specified in sections 8.2.2 and 8.5.1, TAXII Servers are encouraged to implement support for HTTP Basic and Clients are required to implement support for HTTP Basic, though other authentication schemes can also be supported. Implementers can allow operators to disable the use of HTTP Basic in their operations.', 'kb-doc-11-oasis-taxii21-p14-4', 0, 63, '11-oasis-taxii21', 'retrieved', 'BAA35943170090899A124B37E273B3D0AD95BB9991F91ACF446EA229052BA2AA', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-5', 'doc-11-oasis-taxii21', '', 14, 'If the TAXII Server receives a request for any Endpoint that requires authentication, regardless of HTTP method, and either an acceptable Authorization header that grants the client access to that object is not sent with the request or the TAXII Server does not determine via alternate means that the cli ent is authorized to access the resource, then the TAXII Server will respond with an HTTP 401 (Unauthorized) status code and a WWW-Authenticate HTTP header.', 'kb-doc-11-oasis-taxii21-p14-5', 0, 75, '11-oasis-taxii21', 'retrieved', '1AB7D359ADBA8BDC1CAE4AFF455B5796120100FA883FA486731102BAB627052B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-6', 'doc-11-oasis-taxii21', '', 14, 'The WWW-Authenticate header contains one or more challenges, which define which authentication schemes are supported by the TAXII Server. The format of the WWW-Authenticate HTTP header and any challenges are defined in [RFC7235]. To ensure compatibility, it is recommended that any authentication schemes used in challenges be registered in the IANA Hypertext Transfer Protocol (HTTP) Authentication Scheme Registry [HTTP Auth] .', 'kb-doc-11-oasis-taxii21-p14-6', 0, 61, '11-oasis-taxii21', 'retrieved', 'EA93DD55A1F7AA22EF659FFACDDD6FA491C95661A40EDA00E75DAA35891D11FA', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-7', 'doc-11-oasis-taxii21', '', 14, 'A TAXII Server may omit objects, information, or optional properties from any response if the authenticated client is not authorized to receive them, so long as that omission does not violate this specification.', 'kb-doc-11-oasis-taxii21-p14-7', 0, 33, '11-oasis-taxii21', 'retrieved', '614BE738DB6B74E310028461BF764B263531E6F1A752C09A2A092977BA99E609', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-8', 'doc-11-oasis-taxii21', '', 14, '1.6.10 STIX and Other Content TAXII is designed with STIX in mind and to support the exchanging of STIX 2 [STIX Version 2.1] content.', 'kb-doc-11-oasis-taxii21-p14-8', 0, 24, '11-oasis-taxii21', 'retrieved', '5CC763CEBE9B23A3F985DDA9961B12E753A51A29B1C87AE08D580A083A87471F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-9', 'doc-11-oasis-taxii21', '', 14, 'While additional content types are not prohibited, all specific requirements throughout the document are designed for STIX. See section 3.7 for more details.', 'kb-doc-11-oasis-taxii21-p14-9', 0, 23, '11-oasis-taxii21', 'retrieved', '13A173567B69759594415BCE610EF5043484767CC395F9D6EB14DBFC9AB1A5EE', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-10', 'doc-11-oasis-taxii21', '', 14, '1.6.11 Object Lifecycle There are no requirements defined in this specification for how long a TAXII server needs to store a specific object on the server or within a collection after it has been successfully posted to a TAXII collection. If the TAXII server chooses to remove an entire object or any number of versions of the object from the server or collection that is entirely up to the software, its deployment, and the use cases it supports.', 'kb-doc-11-oasis-taxii21-p14-10', 0, 78, '11-oasis-taxii21', 'retrieved', 'F86D51058691983779E9E4AC2297ED70A5E29CA62A5D506EDD78D1F79E318D5A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p14-11', 'doc-11-oasis-taxii21', '', 14, '1.7 Changes from Earlier Versions This section lists all of the major changes from the previous 2.0 version of TAXII.', 'kb-doc-11-oasis-taxii21-p14-11', 0, 20, '11-oasis-taxii21', 'retrieved', '62C1A3A3C68537256289D83362A4A6F04D978520BDFBA7EF0B6E396080BEFB38', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p15-1', 'doc-11-oasis-taxii21', '', 15, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 15 of 79 1.7.1 TAXII 2.1 Major Changes and Additions TAXII 2.1 differs from TAXII 2.0 in the following ways:', 'kb-doc-11-oasis-taxii21-p15-1', 0, 37, '11-oasis-taxii21', 'retrieved', 'BC629A21523C0A82EC34CC881FA366CF945E3B73E7428377B429F129403679E3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p15-2', 'doc-11-oasis-taxii21', '', 15, '1. The DNS SRV record was changed from taxii to taxii2 2. The discovery URL was changed from /taxii/ to /taxii2/ 3. The Manifest Resource was changed to represent individual versions of an object, instead of an object with all of its versions 4. Item based pagination was removed from this version of the specification 5. The section on content negotiation was updated 6. The media types were changed throughout the document 7. Clarification was added to say that API Roots can be relative paths as well as absolute paths 8. Changed version value in API Roots to match media type 9. Changed status resource to allow status on success and pending 10. Add TAXII media type as Accept type in 5.4 and 5.6 since a TAXII error message could be returned 11. HTTP Basic is now a SHOULD implement for the Server 12. Added a DELETE object by ID endpoint 13. Added a versions endpoint for object by ID.', 'kb-doc-11-oasis-taxii21-p15-2', 0, 160, '11-oasis-taxii21', 'retrieved', '7D3B2F36F992FD587CB8DFD7FA133CEDED7508D0ED1E47142E95411AE149880B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p15-3', 'doc-11-oasis-taxii21', '', 15, '14. Added section on Server Implementation Considerations 15. Added a limit URL parameter 16. Added a next URL parameter 17. Added a spec_versions match filter parameter 18. Removed STIX media types and STIX Bundle and replaced with TAXII Envelope 19. Added clarifying text around TAXII timestamps needing millisecond precision 20. Cleaned up and deemphasized text around support for content other than STIX 21. Added user-agent HTTP header description', 'kb-doc-11-oasis-taxii21-p15-3', 0, 68, '11-oasis-taxii21', 'retrieved', 'D81077BE6CA9A92BE7E921475E54E4B11DF5F8B8959B39EB54074CAD972D2A1B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p15-4', 'doc-11-oasis-taxii21', '', 15, 'Please see Appendix C for a list GitHub issues that were resolved for this release.', 'kb-doc-11-oasis-taxii21-p15-4', 0, 15, '11-oasis-taxii21', 'retrieved', '774CF5595EA0AA6ADDDABB6244F9374729227AAC8DC55A35A2B77C9849E93706', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
