VALUES ('doc-11-oasis-taxii21-p16-1', 'doc-11-oasis-taxii21', '', 16, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 16 of 79 2 Data Types This section defines the names and permitted values of common types used throughout this specification.', 'kb-doc-11-oasis-taxii21-p16-1', 0, 38, '11-oasis-taxii21', 'retrieved', '3138CDBC9AA24517DC616CDDC3065A1EAD4D8C69BF2B667202FFBFF189BB6D7B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
