INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-2', 'doc-11-oasis-taxii21', '', 16, 'These types are referenced by the “Type” column in other sections. This table do es not, however, define the meaning of any properties using these types. These types may be further restricted elsewhere in the document.', 'kb-doc-11-oasis-taxii21-p16-2', 0, 36, '11-oasis-taxii21', 'retrieved', '5F8F569FAE4DA83E83597432458967BD9E77366EC229ABBDE1963F289BB00834', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
