INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-4', 'doc-11-oasis-taxii21', '', 16, 'boolean A boolean is a value of either true or false. Properties with this type MUST have a literal (unquoted) value of true or false.', 'kb-doc-11-oasis-taxii21-p16-4', 0, 25, '11-oasis-taxii21', 'retrieved', '10C6E6E1C51514879FD6265510CC1609CD40AE06781368D449ECC4810F94F680', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
