INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-7', 'doc-11-oasis-taxii21', '', 16, 'dictionary A dictionary is a JSON object that captures an arbitrary set of key/value pairs.', 'kb-doc-11-oasis-taxii21-p16-7', 0, 15, '11-oasis-taxii21', 'retrieved', '23928AA12D18D26C31A9B824AD2D391B0A419CEA8862F6FA758BAAC7B9D48313', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
