INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-11', 'doc-11-oasis-taxii21', '', 16, 'identifier An identifier is an RFC 4122-compliant Version 4 UUID. The UUID MUST be generated according to the algorithm(s) defined in RFC 4122, section 4.4 (Version 4 UUID) [RFC4122].', 'kb-doc-11-oasis-taxii21-p16-11', 0, 29, '11-oasis-taxii21', 'retrieved', '1576ECB8CDD00A4CD6609CD107AD414F1A00A0D681570420C20882516BEBF29C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-12', 'doc-11-oasis-taxii21', '', 16, 'integer The integer data type represents a whole number. Unless otherwise specified, all integers MUST be capable of being represented as a signed 54-bit value ([- (2**53)+1, (2**53)-1]) as defined in [RFC7493]. Additional restrictions MAY be placed on the type where it is used.', 'kb-doc-11-oasis-taxii21-p16-12', 0, 44, '11-oasis-taxii21', 'retrieved', '1A1728E0B6C422AC8E8E54B659B7801449CEE5A1CBF07731473EE085A8E9E58A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-13', 'doc-11-oasis-taxii21', '', 16, 'list The list type defines a sequence of values ordered based on how they appear in the list. The phrasing “list of type ” is used to indicate that all values within the list MUST conform to the specified type. For instance, list of type integer means that all values of the list must be of the integer type.', 'kb-doc-11-oasis-taxii21-p16-13', 0, 59, '11-oasis-taxii21', 'retrieved', '46C99720ADD24F545FD947893A96729614860C825FC99CFBEE72E9C6BB82F4A8', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p16-14', 'doc-11-oasis-taxii21', '', 16, 'This specification does not specify the maximum number of allowed values in a list, however every instance of a list MUST have at least one value. Specific TAXII resource properties may define more restrictive upper and/or lower bounds for the length of the list.', 'kb-doc-11-oasis-taxii21-p16-14', 0, 44, '11-oasis-taxii21', 'retrieved', 'ED8FF8959A79771255CDCE25C3B851953C58CFF8EF38044BF56790F51FA167B8', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p17-1', 'doc-11-oasis-taxii21', '', 17, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 17 of 79 Empty lists are prohibited in TAXII and MUST NOT be used as a substitute for omitting optional properties. If the property is required, the list MUST be present and MUST have at least one value.', 'kb-doc-11-oasis-taxii21-p17-1', 0, 55, '11-oasis-taxii21', 'retrieved', '26782A1D62152CFB10FB4A46521383069B0AD5CB18B3DDC56CDE6973C8D0FE7E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p17-2', 'doc-11-oasis-taxii21', '', 17, 'The JSON MTI serialization uses the JSON array type [RFC8259], which is an ordered list of values.', 'kb-doc-11-oasis-taxii21-p17-2', 0, 17, '11-oasis-taxii21', 'retrieved', 'EFF93F9FB6F8B4A73F1BD0B09A7222A199DF249A2A3BE1DDB256D9CAEF8C2F57', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p17-6', 'doc-11-oasis-taxii21', '', 17, 'string The string data type represents a finite-length string of valid characters from the Unicode coded character set [ISO10646] that are encoded in UTF-8. Unicode incorporates ASCII [RFC0020] and the characters of many other international character sets.', 'kb-doc-11-oasis-taxii21-p17-6', 0, 37, '11-oasis-taxii21', 'retrieved', '6DCF6F78B9799EE95944A99A2DD99D84200D7B61C5C3F86FC659F6D4A98986EF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p17-7', 'doc-11-oasis-taxii21', '', 17, 'timestamp The timestamp type defines how timestamps are represented in TAXII and is represented in serialization as a string.', 'kb-doc-11-oasis-taxii21-p17-7', 0, 19, '11-oasis-taxii21', 'retrieved', 'B63BCE175994711B5B542E9DA828BBCA12CC827CCD125B894CB5BACDE72C868D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p17-8', 'doc-11-oasis-taxii21', '', 17, '● The timestamp type MUST be a valid RFC 3339-formatted timestamp [RFC3339] using the format YYYY-MM-DDTHH:MM:SS.ssssssZ Unlike the STIX timestamp type, the TAXII timestamp MUST have microsecond precision.', 'kb-doc-11-oasis-taxii21-p17-8', 0, 28, '11-oasis-taxii21', 'retrieved', 'CEFAD221505C9CEC2E5B69B85E1DD0417E57636B3957615AB66FF3D388664DB2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p17-9', 'doc-11-oasis-taxii21', '', 17, '● The timestamp MUST be represented in the UTC timezone and MUST use the “Z” designation to indicate this.', 'kb-doc-11-oasis-taxii21-p17-9', 0, 19, '11-oasis-taxii21', 'retrieved', '69D4ADF6B660FE37738CAF35DC1565B36FD7A3ECE1FAB2A66F26A5AB30DE8BBF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-1', 'doc-11-oasis-taxii21', '', 18, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 18 of 79 3 TAXII - Core Concepts The TAXII API is described as sets of Endpoints. Each Endpoint is identified by the URL that it is accessible at and the HTTP method that is used to make the request. For example, the "Get Collections" Endpoint is requested by issuing a GET to `{api-root}/collections/`. Each Endpoint identifies its URL, which parameters it accepts (including both path parameters and standard parameters), which features it supports (e.g. filtering), and which content types it defines for request and response. It also identifies common error conditions and provides guidance on how to use the Endpoint.', 'kb-doc-11-oasis-taxii21-p18-1', 0, 118, '11-oasis-taxii21', 'retrieved', '61B6CC2D3D77CFDA591A9E26AC096ABC585BA75C72C9666F02E96B3E8EAC147D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-2', 'doc-11-oasis-taxii21', '', 18, 'This section defines behavior that applies across Endpoints, such as normative requirements to support each Endpoint, sorting, filtering, and error handling.', 'kb-doc-11-oasis-taxii21-p18-2', 0, 21, '11-oasis-taxii21', 'retrieved', 'D69C4A550B92F2802D11DE8C4D0222190C88ED4FD932FA8F87DBAE9053613746', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
