INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-3', 'doc-11-oasis-taxii21', '', 18, '3.1 Endpoints Sections 4, 5 and 6 define the set of TAXII Endpoints used in the TAXII API. The following normative requirements apply to each Endpoint: ● The endpoint path in a requests to a TAXII server MUST end in a trailing slash "/". For example: ○ A request for a resource without any filter parameters /{api- root}/collections/{id}/objects/{object-id}/ ○ A request for a resource with some filter parameters. /{api- root}/collections/{id}/objects/{object-id}/?match[type]=indicator ● TAXII responses with an HTTP success code (200 series) that permit a response body MUST include the appropriate response body for the specified content type as identified in the definition of that Endpoint.', 'kb-doc-11-oasis-taxii21-p18-3', 0, 104, '11-oasis-taxii21', 'retrieved', '8AB60D1758276FDD82D4B862E2CE7142E1AC1B01689E177F2754F1AD431707BC', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-4', 'doc-11-oasis-taxii21', '', 18, '● TAXII responses with an HTTP error code (400-series and 500-series status codes, defined by sections 6.5 and 6.6 of [RFC7231]) that permit a response body (i.e. are not in response to a HEAD request) MAY contain an error message (see section 3.6.1) in the response body.', 'kb-doc-11-oasis-taxii21-p18-4', 0, 47, '11-oasis-taxii21', 'retrieved', 'F1DEA2FEC55C2E27215A93056F0FDAD20A193A7E9FC9AD297F0C7CAAA4AD5F1A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-5', 'doc-11-oasis-taxii21', '', 18, '● All TAXII requests MUST include a media range in the Accept header and MUST include at least one TAXII media range. Requests for TAXII content MUST use the values from section 1.6.8 and SHOULD include the optional version parameter defined in that section.', 'kb-doc-11-oasis-taxii21-p18-5', 0, 44, '11-oasis-taxii21', 'retrieved', '2EF54B3699C60E97A32AFB6BD16890DE2DF2B98D91CAB9DF2A6958A59D1EA0B2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-6', 'doc-11-oasis-taxii21', '', 18, '● All TAXII responses MUST include the appropriate media type and version parameter in the Content-Type header as defined for that Endpoint.', 'kb-doc-11-oasis-taxii21-p18-6', 0, 22, '11-oasis-taxii21', 'retrieved', 'B25514E8556E7683EEEB757C832C71384E23BCBEB3D9974D5B279903B2B7A7EC', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-7', 'doc-11-oasis-taxii21', '', 18, '● TAXII responses SHOULD be the highest version of content that the server supports if the version parameter in the Accept header is omitted during content negotiation.', 'kb-doc-11-oasis-taxii21-p18-7', 0, 27, '11-oasis-taxii21', 'retrieved', 'B3B94491D31911D7D866A73C75DD935A67FA08ED4FB48453C1650CA3259D7F46', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-8', 'doc-11-oasis-taxii21', '', 18, '● Requests with media types in the Accept headers that are defined for that Endpoint MUST NOT result in an HTTP 406 (Not Acceptable) response.', 'kb-doc-11-oasis-taxii21-p18-8', 0, 25, '11-oasis-taxii21', 'retrieved', '4D3DA8059778794CC5965E2EE59BDC4DD7FFE53E775904472D83320479EEC1A2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
