INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-9', 'doc-11-oasis-taxii21', '', 18, '● Requests with a media type in the Content-Type header that is defined for that Endpoint MUST NOT result in an HTTP 415 (Unacceptable Media Type) response.', 'kb-doc-11-oasis-taxii21-p18-9', 0, 27, '11-oasis-taxii21', 'retrieved', '60B3DB31213704819A3E95AD62EC552AB190C9D64087E93F404996DD652A1ECF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
