INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-10', 'doc-11-oasis-taxii21', '', 18, '● Requests with media types in the Accept headers that are not defined for that Endpoint MAY be satisfied with the appropriate content or MAY result in an HTTP 406 (Not Acceptable) response.', 'kb-doc-11-oasis-taxii21-p18-10', 0, 33, '11-oasis-taxii21', 'retrieved', 'FE4BD861868A0FE27C92ACFE099DFC8A84B692F85EB63FB147AA0F86F934A5BA', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
