VALUES ('doc-11-oasis-taxii21-p18-11', 'doc-11-oasis-taxii21', '', 18, '● Requests with a media type in the Content-Type header that is not defined for that Endpoint MAY be satisfied with the appropriate content or MAY result in an HTTP 415 (Unacceptable Media Type) response.', 'kb-doc-11-oasis-taxii21-p18-11', 0, 35, '11-oasis-taxii21', 'retrieved', 'CA897C34DA4CE59AEF6F2AB0DE44584E11A5966432FDD4EEE92C056F97EAE8E3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
