VALUES ('doc-11-oasis-taxii21-p18-13', 'doc-11-oasis-taxii21', '', 18, '● TAXII responses to Endpoints that support filtering MUST filter results per the requirements in section 3.4.', 'kb-doc-11-oasis-taxii21-p18-13', 0, 17, '11-oasis-taxii21', 'retrieved', 'E767798C9C32FC5043BAFC9DE532E95E47E7FD832E4D1529CC8A760A9280FF7A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
