VALUES ('doc-11-oasis-taxii21-p18-14', 'doc-11-oasis-taxii21', '', 18, '● The endpoint definition information in the tables found in sections 4 and 5 is normative.', 'kb-doc-11-oasis-taxii21-p18-14', 0, 16, '11-oasis-taxii21', 'retrieved', '588C10E6A980DEA00E864F479241073EB84EECA23943D3DB370236D9EF13FC15', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
