INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p18-15', 'doc-11-oasis-taxii21', '', 18, 'The following table provides a summary of the Endpoints (URLs and HTTP Methods) defined by TAXII and the Resources they operate on.', 'kb-doc-11-oasis-taxii21-p18-15', 0, 22, '11-oasis-taxii21', 'retrieved', '818FDCF87F30D772A3DC8085849216CE9D2CC6343F97FFEE2D8549B53C90A10E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
