INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p19-1', 'doc-11-oasis-taxii21', '', 19, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 19 of 79', 'kb-doc-11-oasis-taxii21-p19-1', 0, 20, '11-oasis-taxii21', 'retrieved', '6D24AB606D8AD18F4AA42263F4A7DEF8E77D85278451E821E61FDF32F351C6C5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
