INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p19-2', 'doc-11-oasis-taxii21', '', 19, 'URL Methods Resource Type Core Concepts (section 4) /taxii2/ GET discovery {api-root}/ GET api {api-root}/status/{status-id}/ GET status Collections (section 5) {api-root}/collections/ GET collections {api-root}/collections/{id}/ GET collection {api-root}/collections/{id}/manifest/ GET manifest {api-root}/collections/{id}/objects/ GET, POST envelope {api-root}/collections/{id}/objects/{object-id}/ GET, DELETE envelope {api-root}/collections/{id}/objects/{object-id}/versions/ GET versions Channels (section 6) TBD in a future version', 'kb-doc-11-oasis-taxii21-p19-2', 0, 48, '11-oasis-taxii21', 'retrieved', 'CBFB6407B3E5E0CD8960EFE70A29E573640860D6C830F45E96DC3D0067155649', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
