INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p19-3', 'doc-11-oasis-taxii21', '', 19, '3.2 HTTP Headers This section summarizes the HTTP headers and defines custom headers used by this specification.', 'kb-doc-11-oasis-taxii21-p19-3', 0, 17, '11-oasis-taxii21', 'retrieved', '152108AC4234AE6BEF0D70961488767F3FDB56EBE67CC18AFFA6D774CD3C9C9A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p19-4', 'doc-11-oasis-taxii21', '', 19, 'Type Description Standard Headers Accept The Accept header is used by HTTP Requests to specify which Content-Types are acceptable in response. TAXII defines a media type and an optional version parameter that can be used in the Accept header. See section 5.3.2 of [RFC7231].', 'kb-doc-11-oasis-taxii21-p19-4', 0, 44, '11-oasis-taxii21', 'retrieved', '1155AF84AED1E3599FBE36C826F02EB1E9DDB3A1E2A7A54E43DF510FF52D27AB', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-1', 'doc-11-oasis-taxii21', '', 20, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 20 of 79 Authorization The Authorization header is used by HTTP Requests to specify authentication credentials. See section 4.2 of [RFC7235].', 'kb-doc-11-oasis-taxii21-p20-1', 0, 38, '11-oasis-taxii21', 'retrieved', '218AC71E6852AF77F43F0163A16C2058A4CFEFC1579CC08F24C6FE91230F1C73', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-2', 'doc-11-oasis-taxii21', '', 20, 'Content-Type The Content-Type header is used by HTTP to identify the format of HTTP Requests and HTTP Responses. TAXII defines a media type and an optional version parameter that can be used in the Content- Type header. See section 3.1.1.5 of [RFC7231].', 'kb-doc-11-oasis-taxii21-p20-2', 0, 42, '11-oasis-taxii21', 'retrieved', '767DEF8BE858262E9715B6D86F06B6C5009C3C36D0C2B02DF45E2DBE3D23724B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-3', 'doc-11-oasis-taxii21', '', 20, 'User-Agent The User-Agent header is used by HTTP to identify the TAXII Client software name and version. TAXII Clients SHOULD use the User- Agent header in requests to a TAXII Server as defined in section 5.5.3 of [RFC7231].', 'kb-doc-11-oasis-taxii21-p20-3', 0, 38, '11-oasis-taxii21', 'retrieved', 'A7D8C1DA855B90FB63E87BDDC37A425AC1F8AF63DDC88ED6DCEC51500058092F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-4', 'doc-11-oasis-taxii21', '', 20, 'WWW-Authenticate The WWW-Authenticate header is used by HTTP Responses to indicate that authentication is required and to specify the authentication schemes and parameters that are supported. See section 4.1 of [RFC7235].', 'kb-doc-11-oasis-taxii21-p20-4', 0, 31, '11-oasis-taxii21', 'retrieved', '9231714CB34ACFEFC2A8E0FE9B5D9245171781D62BA6D3D40B735C5C8ED7D4F4', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-5', 'doc-11-oasis-taxii21', '', 20, 'Custom Headers X-TAXII-Date-Added-First The X-TAXII-Date-Added-First header is an extension header. It indicates the date_added timestamp of the first object of the response.', 'kb-doc-11-oasis-taxii21-p20-5', 0, 22, '11-oasis-taxii21', 'retrieved', '40A251AF3B9AB9AEB9F257C3A85CBB15B7F5900CB0784EB04B4EED5E28DBD759', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-6', 'doc-11-oasis-taxii21', '', 20, 'The value of this header MUST be a timestamp. All HTTP 200 series responses to the following endpoints MUST include the X- TAXII-Date-Added-First header: ● GET {api-root}/collections/{id}/manifest/ ● GET {api-root}/collections/{id}/objects/ ● GET {api-root}/collections/{id}/objects/{object-id}/ ● GET {api-root}/collections/{id}/objects/{object-id}/versions/ Behaviour of this header on any other endpoint, is not defined.', 'kb-doc-11-oasis-taxii21-p20-6', 0, 47, '11-oasis-taxii21', 'retrieved', 'A3902434872D1FC9F5342853FB4DA557210907CC53AC14C7AFB9C61049B95225', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-7', 'doc-11-oasis-taxii21', '', 20, 'X-TAXII-Date-Added-Last The X-TAXII-Date-Added-Last header is an extension header. It indicates the date_added timestamp of the last object of the response.', 'kb-doc-11-oasis-taxii21-p20-7', 0, 20, '11-oasis-taxii21', 'retrieved', '37FFF08CD519CF579D6164BB268803BDC2017CF4D7B3DC58357C2DA1436D2B1C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p20-8', 'doc-11-oasis-taxii21', '', 20, 'The value of this header MUST be a timestamp. All HTTP 200 series responses to the following endpoints MUST include the X- TAXII-Date-Added-Last header: ● GET {api-root}/collections/{id}/manifest/ ● GET {api-root}/collections/{id}/objects/ ● GET {api-root}/collections/{id}/objects/{object-id}/ ● GET {api-root}/collections/{id}/objects/{object-id}/versions/ Behaviour of this header on any other endpoint, is not defined.', 'kb-doc-11-oasis-taxii21-p20-8', 0, 47, '11-oasis-taxii21', 'retrieved', 'E983554734C6E8DCE69010775B86145729914D1DC2707D3420335A3E089B1A14', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
