INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-1', 'doc-11-oasis-taxii21', '', 21, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 21 of 79 3.3 Sorting For Object and Manifest Endpoints, objects returned MUST be sorted in ascending order by the date it was added. Meaning, the most recently added object is last in the list.', 'kb-doc-11-oasis-taxii21-p21-1', 0, 52, '11-oasis-taxii21', 'retrieved', '689ED931C25C170E33E08FE153C0A4DF39B3DF9C44AD1FFF129D539EDE38E7E4', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-2', 'doc-11-oasis-taxii21', '', 21, 'The Collections Endpoint MUST return Collection Resources in a consistent sort order across multiple requests.', 'kb-doc-11-oasis-taxii21-p21-2', 0, 15, '11-oasis-taxii21', 'retrieved', 'E8BA65BCF75327874AEAFC3679F868E80B441DBACF5D09B2F51E43831D36A10B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
