INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-3', 'doc-11-oasis-taxii21', '', 21, '3.4 Filtering This section defines the URL query parameters used for matching and filtering content. A TAXII Client can request specific content from a TAXII Server by specifying a set of filters included in the request to the server. The URL query parameters listed below specifies what to include in the response from the TAXII Server. If no URL query parameter is specified then the TAXII Client is requesting that all content be returned for that Endpoint, subject to any default behaviors as listed below.', 'kb-doc-11-oasis-taxii21-p21-3', 0, 85, '11-oasis-taxii21', 'retrieved', '8F55FD11420DDAE95485279E3310ECB98255E45AE05B66A72637BF385214BE42', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-4', 'doc-11-oasis-taxii21', '', 21, 'If any of the URL query parameters are malformed, the TAXII Server MUST return an HTTP 400 (Bad Request) status code.', 'kb-doc-11-oasis-taxii21-p21-4', 0, 21, '11-oasis-taxii21', 'retrieved', '14C7D20D83978319D4E184D1342765A310D9B3A42A6B7FA911C3E8C495F4A949', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-5', 'doc-11-oasis-taxii21', '', 21, 'URL Query Parameters Description added_after A single timestamp that filters objects to only include those objects added after the specified timestamp. The value of this parameter is a timestamp.', 'kb-doc-11-oasis-taxii21-p21-5', 0, 29, '11-oasis-taxii21', 'retrieved', '524ED3F4F07FA2F84E57CE7BE3A202CCAC3DD6B03BF3966B7C04AF6649633AC5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-8', 'doc-11-oasis-taxii21', '', 21, 'If no added_after URL query parameter is provided, the server MUST return the oldest objects matching the request first. For example, if a server has 100 objects (0-99) and limits requests to 10 objects at a time and a client makes a request without an added_after URL query parameter, the server would start at record 0 looking for a match and work its way up from oldest to newest finding 10 objects that matched the request.', 'kb-doc-11-oasis-taxii21-p21-8', 0, 76, '11-oasis-taxii21', 'retrieved', '2742DE38D17A52915170AA088D0A12F1B8BFCB01F3FBD6738A4D785241A0FF50', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-9', 'doc-11-oasis-taxii21', '', 21, 'The added_after parameter is not in any way related to dates or times in a STIX object or any other CTI object.', 'kb-doc-11-oasis-taxii21-p21-9', 0, 22, '11-oasis-taxii21', 'retrieved', '2D912A68715E435D5955D5A4DA7A0EE3126CF0C748BF7574B0E1341DCB59E2BD', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-10', 'doc-11-oasis-taxii21', '', 21, 'Note: The HTTP Date header can be used to identify and correct any time skew between client and server.', 'kb-doc-11-oasis-taxii21-p21-10', 0, 19, '11-oasis-taxii21', 'retrieved', '8165052F9E9CFA9AAF1193591DF0E89D56FE8D2615D1F64722B3C5EF9474A631', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
