INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-11', 'doc-11-oasis-taxii21', '', 21, 'limit A single integer value that indicates the maximum number of objects that the client would like to receive in a single response.', 'kb-doc-11-oasis-taxii21-p21-11', 0, 23, '11-oasis-taxii21', 'retrieved', '123B525629E732FCA4AD0EBA9A12A0359976B78BE9C9DB549491BF791955626C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-13', 'doc-11-oasis-taxii21', '', 21, '● Responses to requests where the client provided a limit MUST NOT contain more objects than requested.', 'kb-doc-11-oasis-taxii21-p21-13', 0, 17, '11-oasis-taxii21', 'retrieved', '14BDADC1E3AD29FE555A03EB68E0C6C81CFE7C5A0743484229BA62B42A5786C2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-14', 'doc-11-oasis-taxii21', '', 21, '● If the number of objects available for the response is less than or equal to both the client requested and server-imposed limit, then all objects MUST be included in the response.', 'kb-doc-11-oasis-taxii21-p21-14', 0, 32, '11-oasis-taxii21', 'retrieved', '42BC2EF9F71A3A46413987F1377336A9634092F492F633186FC9012F8D0D0D07', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-15', 'doc-11-oasis-taxii21', '', 21, '● A response to a request with a defined client limit that is greater than the number of objects that the server is willing or able to provide MAY result in a response with fewer objects than what was requested.', 'kb-doc-11-oasis-taxii21-p21-15', 0, 40, '11-oasis-taxii21', 'retrieved', '5DC5953CDAF233CAE8049956511505B20BE229F50D1C3A1F978D5DB45C1DB163', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p21-16', 'doc-11-oasis-taxii21', '', 21, '● If more objects are available either because the client requested that they be limited via the limit parameter or the server limited them, then the', 'kb-doc-11-oasis-taxii21-p21-16', 0, 26, '11-oasis-taxii21', 'retrieved', '1ECC5A90713588ADB3D98C5C65602C201794078E11725EFF1002254415DDFDCB', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
