INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-1', 'doc-11-oasis-taxii21', '', 22, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 22 of 79 response envelope MUST have a value of true in the more property and MAY have an appropriate value in the next property.', 'kb-doc-11-oasis-taxii21-p22-1', 0, 42, '11-oasis-taxii21', 'retrieved', '567F88B89F00477455C58C57AF743B7C0AACA281A957E1380A5F9FDB4FF4DE92', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-2', 'doc-11-oasis-taxii21', '', 22, 'next A single string value that indicates the next record or set of records in the dataset that the client is requesting. A client would get this value from the TAXII Envelope and would use this value along with the original query/filter parameters to paginate through additional records. This value is opaque to clients and may vary between server implementations.', 'kb-doc-11-oasis-taxii21-p22-2', 0, 60, '11-oasis-taxii21', 'retrieved', '4890B10468C6B07FF87148D1FD48D803FA40CE8A20B17290E2F980AECEEBF1F3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-3', 'doc-11-oasis-taxii21', '', 22, 'match[ ] The match parameter defines filtering on the specified . The list of fields that MUST be supported is defined per Endpoint as defined in sections 4, 5, and 6.', 'kb-doc-11-oasis-taxii21-p22-3', 0, 31, '11-oasis-taxii21', 'retrieved', '948DD9364AFE177BA750563A97B079B38C2CDDE12B82B575FB97D65B423F9236', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-4', 'doc-11-oasis-taxii21', '', 22, 'The match parameter can be specified any number of times, where each match instance specifies an additional filter to be applied to the resulting data and each MUST NOT occur more than once in a request. Said another way, all match fields are ANDed together.', 'kb-doc-11-oasis-taxii21-p22-4', 0, 45, '11-oasis-taxii21', 'retrieved', 'FF02CAF0472F4605E49D03347C536386D2114E330F1A03315471DC4C4F763401', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-5', 'doc-11-oasis-taxii21', '', 22, 'All parameters are defined in the following table. Requests MAY use a not defined in this specification, and servers MAY ignore fields they do not understand.', 'kb-doc-11-oasis-taxii21-p22-5', 0, 26, '11-oasis-taxii21', 'retrieved', '2F701146BE6569DB5951A3C91CC391B9E5E2EC222D5ED28A80088653325D2F12', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-6', 'doc-11-oasis-taxii21', '', 22, 'Each field MAY contain one or more values. Multiple values are separated by a comma (U+002C COMMA, “,”) without any spaces. If multiple values are present, the match is treated as a logical OR. For instance, ?match[type]=incident,malware specifies a filter for objects that are of type incident OR malware.', 'kb-doc-11-oasis-taxii21-p22-6', 0, 49, '11-oasis-taxii21', 'retrieved', '2917A35596627EBA32C5B384973F4470426C01EA1E96B2A3BD2174CC187BA829', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-7', 'doc-11-oasis-taxii21', '', 22, 'Examples ?match[type]=campaign,malware,threat-actor ?match[type]=incident&match[version]=2016-01-01T01:01:01.000Z', 'kb-doc-11-oasis-taxii21-p22-7', 0, 3, '11-oasis-taxii21', 'retrieved', '18B6053FC8A4576BF37DB12467809E62D7D578DCCFD61B98B9FD85DD6DD9E454', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
