INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-8', 'doc-11-oasis-taxii21', '', 22, '3.4.1 Supported Fields for Match Match Field Description id The identifier of the object(s) that are being requested. When searching for a STIX Object, this is a STIX ID.', 'kb-doc-11-oasis-taxii21-p22-8', 0, 29, '11-oasis-taxii21', 'retrieved', '7BE0C415E9D8E987763DB998039643A76DD2DA6942BF15BA0BC482FB84246FB5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p22-9', 'doc-11-oasis-taxii21', '', 22, 'Examples ?match[id]=indicator--3600ad1b-fff1-4c98-bcc9-4de3bc2e2ffb ?match[id]=indicator--3600ad1b-fff1-4c98-bcc9-4de3bc2e2ffb,sighting-- 4600ad1b-fff1-4c58-bcc9-4de3bc5e2ffd spec_version The specification version(s) of the STIX object that are being requested. A response to a request with the spec_version match MUST NOT include any specification versions that are not included in this parameter. If no spec_version parameter is provided, the server MUST return only the latest', 'kb-doc-11-oasis-taxii21-p22-9', 0, 51, '11-oasis-taxii21', 'retrieved', '2761DEE7EB9409BD4C1FFD1F22A871D63899E2D5986C85891FD0D4648983AF39', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
