INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-1', 'doc-11-oasis-taxii21', '', 23, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 23 of 79 specification version that it can provide for each object matching the remainder of the request.', 'kb-doc-11-oasis-taxii21-p23-1', 0, 35, '11-oasis-taxii21', 'retrieved', '404CCA690A2285812CAC3863EDC82960C7778F9B89C8547C4C5AAE8477D7DD47', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
