VALUES ('doc-11-oasis-taxii21-p23-2', 'doc-11-oasis-taxii21', '', 23, 'Examples ?match[spec_version]=2.0 ?match[spec_version]=2.0,2.1 type The type of the object(s) that are being requested. Only the types listed in this parameter are permitted in the response.', 'kb-doc-11-oasis-taxii21-p23-2', 0, 25, '11-oasis-taxii21', 'retrieved', '2DE3FDD5105D520B0EE0DC8E2C3DCFCA26968EDC18151C5E43362C7449EB4A3D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
