INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-3', 'doc-11-oasis-taxii21', '', 23, 'Requests for types defined in [STIX Version 2.1] MUST NOT result in an error due to an invalid type.', 'kb-doc-11-oasis-taxii21-p23-3', 0, 19, '11-oasis-taxii21', 'retrieved', 'E0A05A2AE449C7D9D8FDE9DDF63626417B76CC26EEA4DAE413E0C48938ABB87B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
