INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-5', 'doc-11-oasis-taxii21', '', 23, 'Examples ?match[type]=indicator ?match[type]=indicator,sighting version The version(s) of the object(s) that are being requested from either an object or manifest endpoint. If no version parameter is provided, the server MUST return only the latest version for each object matching the remainder of the request.', 'kb-doc-11-oasis-taxii21-p23-5', 0, 43, '11-oasis-taxii21', 'retrieved', '9217AEC8FB82363ED3D75979053D54A10B656DFDDCF40044F233F65A59BBFC9F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-6', 'doc-11-oasis-taxii21', '', 23, 'If a STIX object is not versioned (and therefore does not have a modified timestamp) then this version parameter MUST use the created timestamp. If an object does not have a created or modified timestamp or any other version information that can be used, then the server should use a value for the version that is consistent to the server.', 'kb-doc-11-oasis-taxii21-p23-6', 0, 60, '11-oasis-taxii21', 'retrieved', '563254E73482B3B6EFE82A2B90D182DAB84F13BCD285B6CE873C07CCB7EBFC1A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-7', 'doc-11-oasis-taxii21', '', 23, 'Requests MUST NOT contain any duplicate version parameters, meaning, each keyword (all, first, and last) and any specific version ( ) MUST NOT occur more than once in a request. However, multiple different specific versions MAY be specified in the same request.', 'kb-doc-11-oasis-taxii21-p23-7', 0, 42, '11-oasis-taxii21', 'retrieved', 'CC39FF92BD2AC6D08F4BEC0CDDE2B3159F8B15502553BF178C202069984FA44E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-8', 'doc-11-oasis-taxii21', '', 23, 'Valid values for the version parameter are: ● last - requests the latest version of an object. This is the default parameter value if no other version parameter is provided.', 'kb-doc-11-oasis-taxii21-p23-8', 0, 30, '11-oasis-taxii21', 'retrieved', '9100465471828461A80B3EED3A5BCCC80FB1C18E9EF52D7B34F92CF9AA03CA71', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-10', 'doc-11-oasis-taxii21', '', 23, '● all - requests all versions of an object. The all keyword MUST NOT be used with any other version parameter.', 'kb-doc-11-oasis-taxii21-p23-10', 0, 21, '11-oasis-taxii21', 'retrieved', '9B887026612AE59906154F3128302B9382CF2C6318B918CB2A70D4AD476FB597', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
