INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-12', 'doc-11-oasis-taxii21', '', 23, '○ For STIX objects, this filter option requests objects whose modified time matches exactly the provided value and the value MUST follow the rules for timestamp as defined in [STIX Version 2.1].', 'kb-doc-11-oasis-taxii21-p23-12', 0, 32, '11-oasis-taxii21', 'retrieved', 'BCE13C259C12D24E33796C40613EF5E4A57B0A826ECCDA1E1F15E5D34E6E25EA', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p23-13', 'doc-11-oasis-taxii21', '', 23, '○ For example: "2016-01-01T01:01:01.000Z" tells the server to return the exact STIX object(s) that matched the modified time of "2016-01-01T01:01:01.000Z".', 'kb-doc-11-oasis-taxii21-p23-13', 0, 20, '11-oasis-taxii21', 'retrieved', '8B72A93BD98D2203C5796A6322B6656867FB239AF6B780E2180BB6586D2425E2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
