INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-1', 'doc-11-oasis-taxii21', '', 24, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 24 of 79 ○ For non-STIX objects this value MAY, be any string that represents the version of that object type. If the target format does not support object versions, this parameter MUST be ignored.', 'kb-doc-11-oasis-taxii21-p24-1', 0, 52, '11-oasis-taxii21', 'retrieved', '471DBE0F666A1885C43D2EEEF02829FDAD1003F87B361EBE68F16643A17D3793', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
