INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-2', 'doc-11-oasis-taxii21', '', 24, 'Examples ?match[version]=all ?match[version]=last,first ?match[version]=first,2018-03-02T01:01:01.123Z,last ?match[version]=2016-03-23T01:01:01.000Z,2018-03-02T01:01:01.123Z', 'kb-doc-11-oasis-taxii21-p24-2', 0, 5, '11-oasis-taxii21', 'retrieved', 'A57101BE07BE421E5628CBA78C3DB74D40EF8A9D40B9DE9BA5CE35ED11D95C03', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-3', 'doc-11-oasis-taxii21', '', 24, '3.5 Pagination TAXII 2.1 supports pagination of large result sets on certain endpoints. These endpoints return results sorted in ascending order by the date they were added to the collection (see section 3.3). The server may limit the number of responses in response to a query, either as the result of a server -specified limit or in response to a limit parameter passed by the client as part of a query (see section 3.4).', 'kb-doc-11-oasis-taxii21-p24-3', 0, 74, '11-oasis-taxii21', 'retrieved', 'C1455413C184927CFDA10DF7F7DF766263B378CC4092C6032FDC092CEA773B27', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-4', 'doc-11-oasis-taxii21', '', 24, 'If more objects are available, either because the client requested that they be limited via the limit parameter or the server limited them, then the response envelope MUST have a value of true in the more property and MAY have an appropriate value in the next property.', 'kb-doc-11-oasis-taxii21-p24-4', 0, 47, '11-oasis-taxii21', 'retrieved', '08EED6F681E205F89559771995592BEE5E0BF0D35D199E40579DD45D26E50B99', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-5', 'doc-11-oasis-taxii21', '', 24, 'If the more property is set to true and the next property is populated then the client can paginate through the remaining records using the next URL parameter along with the same original query options.', 'kb-doc-11-oasis-taxii21-p24-5', 0, 35, '11-oasis-taxii21', 'retrieved', '8BD6B86C35CD41644C89011557D340199F2E13CD8FDD3D912416A0EF3AF945FF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-6', 'doc-11-oasis-taxii21', '', 24, 'If the more property is set to true and the next property is empty then the client may paginate through the remaining records by using the added_after URL parameter with the date/time value from the X- TAXII-Date-Added-Last header along with the same original query options.', 'kb-doc-11-oasis-taxii21-p24-6', 0, 45, '11-oasis-taxii21', 'retrieved', '8C3BB66EC1B31992C7F97E48DABDAB0CEDC715962DBCC561A1B496744467E916', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-7', 'doc-11-oasis-taxii21', '', 24, 'It is possible for the server to return "more": true in a response, yet present no additional objects in the follow-on query. This can occur when the additional objects are deleted from a collection between requests.', 'kb-doc-11-oasis-taxii21-p24-7', 0, 36, '11-oasis-taxii21', 'retrieved', 'B59611B4674FF50AEA8A883D37E618D2AFE98928907A767ED681A189140864BB', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-10', 'doc-11-oasis-taxii21', '', 24, '● A client will make a request and the server will respond with the first 100 records.', 'kb-doc-11-oasis-taxii21-p24-10', 0, 17, '11-oasis-taxii21', 'retrieved', '06F3EAA52BFBABA26897BBE502F9C4BBF7468015CF12DD60DE1190E39B19981B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-11', 'doc-11-oasis-taxii21', '', 24, '○ The server will also populate the two X headers for TAXII, X-TAXII-Date-Added-First and X-TAXII-Date-Added-Last. These headers will contain the date/time value of when the first and last records of the 100 returned records were added to the TAXII server.', 'kb-doc-11-oasis-taxii21-p24-11', 0, 40, '11-oasis-taxii21', 'retrieved', '3CF687BA5F29F0432DB6AB1F1A5D27CEAB8B8A1E06F499740EE927C26B202DB2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-12', 'doc-11-oasis-taxii21', '', 24, '○ The server will also set the more property to a value of true and may set the next property to an appropriate value on the TAXII envelope.', 'kb-doc-11-oasis-taxii21-p24-12', 0, 28, '11-oasis-taxii21', 'retrieved', 'AF482C539A962DCA1FC79428E1C3C784E9847F7254850AAF4BA950D6B76115B5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-13', 'doc-11-oasis-taxii21', '', 24, '● When a client wants to obtain the next 100 records, the client will do either: ○ Provided the same query/filter parameters that it originally used along with populating the next URL parameter with the value from the next property on the previous TAXII envelope response.', 'kb-doc-11-oasis-taxii21-p24-13', 0, 46, '11-oasis-taxii21', 'retrieved', '95339C7507BA9A4DAE3FA80B35E0A6797E2CEC27A50522187C45EEECD6AD109E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p24-14', 'doc-11-oasis-taxii21', '', 24, '○ Or provide the same query/filter parameters that it originally used along with the date/time value from the X-TAXII-Date-Added-Last in the added_after URL parameter 3.6 Errors TAXII primarily relies on the standard HTTP error semantics (400-series and 500-series status codes, defined by sections 6.5 and 6.6 of [RFC7231]) to allow TAXII Servers to indicate when an error has', 'kb-doc-11-oasis-taxii21-p24-14', 0, 58, '11-oasis-taxii21', 'retrieved', '5DF3434F25960E98736546084B8B1C32CAEBAA02E4696BC4BE41616804908EED', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p25-1', 'doc-11-oasis-taxii21', '', 25, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 25 of 79 occurred. For example, an HTTP 404 (Not Found) status code in response to a request to get information about a Collection means that the Collection could not be found. The tables defining the Endpoint s in sections 4 and 5 identify common errors and which response should be used, but are not exhaustive and do not describe all possible errors.', 'kb-doc-11-oasis-taxii21-p25-1', 0, 80, '11-oasis-taxii21', 'retrieved', 'FB5C93DEEE4D037156989211921456C7A2CCFD5728AECFEC3E31F9404E20F3B9', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p25-2', 'doc-11-oasis-taxii21', '', 25, 'In addition to this, TAXII defines an error message structure that is provided in the response body when an error status is being returned. It does not, however, define any error codes or error conditions beyond those defined by HTTP.', 'kb-doc-11-oasis-taxii21-p25-2', 0, 40, '11-oasis-taxii21', 'retrieved', 'E93F5B7C0B480DC4E3F1A65DB2630F2BD6B2904B2221A3339F5A5A72FB827806', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p25-3', 'doc-11-oasis-taxii21', '', 25, '3.6.1 Error Message Message Type: error The error message is provided by TAXII Servers in the response body when returning an HTTP error status and contains more information describing the error, including a human-readable title and description, an error_code and error_id, and a details structure to capture further structured information about the error. All of the properties are application-specific, and clients shouldn''t assume consistent meaning across TAXII Servers even if the codes, IDs, or titles are the same.', 'kb-doc-11-oasis-taxii21-p25-3', 0, 78, '11-oasis-taxii21', 'retrieved', 'D21EAFDE262BC21503F2C32F3B3B6125CA1B56AD04CEC5B4875FF5D9DC9C4BE6', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p25-4', 'doc-11-oasis-taxii21', '', 25, 'Property Name Type Description title (required) string A human readable plain text title for this error.', 'kb-doc-11-oasis-taxii21-p25-4', 0, 16, '11-oasis-taxii21', 'retrieved', '1473595156FE8078F70E260B4899E48B8DEB7BB5B8839A23FBDB5A43768C3051', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
