INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p26-3', 'doc-11-oasis-taxii21', '', 26, '3.7 Envelope Resource Resource Name: envelope The envelope is a simple wrapper for STIX 2 content. When returning STIX 2 content in a TAXII response the HTTP root object payload MUST be an envelope. This specification does not define any other form of content wrapper for objects outside of STIX content.', 'kb-doc-11-oasis-taxii21-p26-3', 0, 51, '11-oasis-taxii21', 'retrieved', '42BD392C352EFF7ACF72A519D8626A63CECBAB4485EA841E26931040C0561683', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
