VALUES ('doc-11-oasis-taxii21-p27-5', 'doc-11-oasis-taxii21', '', 27, '3.8 Property Names ● All property names and string literals MUST be exactly the same, including case, as the names listed in the property tables in this specification.', 'kb-doc-11-oasis-taxii21-p27-5', 0, 28, '11-oasis-taxii21', 'retrieved', 'F1C1924186A6D56F21273388372B8931A96655AB6474576D81D5F1D8CA027F1C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
