INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p27-8', 'doc-11-oasis-taxii21', '', 27, '3.9 DNS SRV Names Organizations that choose to implement a DNS SRV record in their DNS server to advertise the location of their TAXII Server MUST use the service name taxii2. As defined in [RFC2782], the service name is defined without an underscore, and an underscore is added to construct the correct name in the actual DNS SRV record. The protocol for this DNS SRV record MUST be tcp.', 'kb-doc-11-oasis-taxii21-p27-8', 0, 69, '11-oasis-taxii21', 'retrieved', '6E1FFC462FEB386516DA8B8B2BF6EB01D733AC96B8166D91C733179DB6E03323', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p27-9', 'doc-11-oasis-taxii21', '', 27, 'Examples The following example is for a DNS SRV record advertising a TAXII Server for the domain “example.com” located at taxii-hub-1.example.com:443: _taxii2._tcp.example.com. 86400 IN SRV 0 5 443 taxii-hub-1.example.com', 'kb-doc-11-oasis-taxii21-p27-9', 0, 29, '11-oasis-taxii21', 'retrieved', 'F54894426A08B7DFA2C85BF811ED7A0F6D51D2159E669AD2A8BABAD0353E3AA0', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
