INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p28-1', 'doc-11-oasis-taxii21', '', 28, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 28 of 79 4 TAXII API - Server Information The following table provides a summary of the Server Information Endpoints (URLs and HTTP Methods) defined by TAXII and the Resources they operate on.', 'kb-doc-11-oasis-taxii21-p28-1', 0, 50, '11-oasis-taxii21', 'retrieved', 'C763242458EC5DC63538194B82861C63B408689204F2B64AD4DAAF0D9471D986', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
