INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p28-3', 'doc-11-oasis-taxii21', '', 28, '4.1 Server Discovery This Endpoint provides general information about a TAXII Server, including the advertised API Roots. It''s a common entry point for TAXII Clients into the data and services provided by a TAXII Server. For example, clients auto-discovering TAXII Servers via the DNS SRV record defined in section 1.6.1 will be able to automatically retrieve a discovery response for that server by requesting the /taxii2/ path on that domain.', 'kb-doc-11-oasis-taxii21-p28-3', 0, 70, '11-oasis-taxii21', 'retrieved', '2283EC6EBB09757459B4086372762214DB6D2979A698972365714800B27656EF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
