INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p30-2', 'doc-11-oasis-taxii21', '', 30, '4.1.1 Discovery Resource Resource Name: discovery The discovery resource contains information about a TAXII Server, such as a human-readable title, description, and contact information, as well as a list of API Roots that it is advertising. It also has an indication of which API Root it considers the default, or the one to use in the absence of another information/user choice.', 'kb-doc-11-oasis-taxii21-p30-2', 0, 61, '11-oasis-taxii21', 'retrieved', '4E9505C4E72882D6C6096564F86DFC5AEFA8EC947B8A0CDD2ED6CFA96FFFC918', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
