INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p30-9', 'doc-11-oasis-taxii21', '', 30, 'API Root URLs MUST be HTTPS absolute URLs or relative URLs. API Root relative URLs MUST begin with a single `/` character and MUST NOT begin with `//` or ''../". API Root URLs MUST NOT contain a URL query component.', 'kb-doc-11-oasis-taxii21-p30-9', 0, 40, '11-oasis-taxii21', 'retrieved', 'EED1AB0F861D7C6DC1BA5E294F7F2AC29901587A03117A7E9CDF94971AE30340', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
