INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p33-4', 'doc-11-oasis-taxii21', '', 33, 'max_content_length (required) integer The maximum size of the request body in octets (8-bit bytes) that the server can support. The value of the max_content_length MUST be a positive integer greater than zero. This applies to requests only and is determined by the server. Requests with total body length values smaller than this value MUST NOT result in an HTTP 413 (Request Entity Too Large) response. If for example, the server supported 100 MB of data, the value for this property would be determined by 100*1024*1024 which equals 104,857,600. This property contains useful information for the client when it POSTs requests to the Add Objects endpoint.', 'kb-doc-11-oasis-taxii21-p33-4', 0, 105, '11-oasis-taxii21', 'retrieved', 'A68C540237DC6F5C19B985E8E32C5FED606F236AC086B97BCF6B7DDB12E546AC', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
