INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p33-5', 'doc-11-oasis-taxii21', '', 33, '4.3 Get Status This Endpoint provides information about the status of a previous request. In TAXII 2.1, the only request that can be monitored is one to add objects to a Collection (see section 5.5). It is typically used by TAXII Clients to monitor a POST request that they made in order to take action when it is complete.', 'kb-doc-11-oasis-taxii21-p33-5', 0, 59, '11-oasis-taxii21', 'retrieved', '3E6E6628E4453151127B2E4E7AD1AAB7D8397E9C051057FA65110BD11D201219', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p33-6', 'doc-11-oasis-taxii21', '', 33, 'TAXII Servers SHOULD accept queries for a given status ID for at least 24 hours after the server has finished processing the request. Once a TAXII client receives a status resource where the status value is complete for a given status ID it SHOULD never pull for that status ID again. If the TAXII Server receives a request on the status endpoint for a status ID that is no longer available , the server MUST return an HTTP status of 404 (Not Found).', 'kb-doc-11-oasis-taxii21-p33-6', 0, 83, '11-oasis-taxii21', 'retrieved', '879B49C231500D58A50826E00C5A00879A04C30B5ECBB47B764C3C5EB0D2E040', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
