INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p36-1', 'doc-11-oasis-taxii21', '', 36, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 36 of 79 4.3.1 Status Resource Resource Name: status The status resource represents information about a request to add objects to a Collection. It contains information about the status of the request, such as whether or not it''s completed (status) and MAY contain the status of individual objects within the request (i.e. whether they are still pending, completed and failed, or completed and succeeded).', 'kb-doc-11-oasis-taxii21-p36-1', 0, 81, '11-oasis-taxii21', 'retrieved', '2C7FDB88A51DD9F74149864CB4148B1ED556F2EB07CF2A56D9DE4879219D91FD', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p36-2', 'doc-11-oasis-taxii21', '', 36, 'The status resource is returned in two places: as a response to the initial POST request (see section 5.5) and in response to a get status request (see section 4.3), which can be made after the initial request to continuously monitor its status.', 'kb-doc-11-oasis-taxii21-p36-2', 0, 43, '11-oasis-taxii21', 'retrieved', '3ABB9DCBA8DB8A8E7FF9D1DDDD767219C83CCCA61DBF0DFE3FACB79B2781111A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p36-3', 'doc-11-oasis-taxii21', '', 36, 'The list of objects that failed to be added, are still pending, or have been successfully added is a simple type, named status-details, that contains the identifier of the object (e.g., for STIX objects, their id), its version, and an optional message indicating additional details.', 'kb-doc-11-oasis-taxii21-p36-3', 0, 45, '11-oasis-taxii21', 'retrieved', '28EE2160B4306758B0E36D676BDBC2F68E124C78CD49F3BF930E9CC0D2B7FBAE', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
