VALUES ('doc-11-oasis-taxii21-p36-4', 'doc-11-oasis-taxii21', '', 36, 'Property Name Type Description id (required) identifier The identifier of this Status resource.', 'kb-doc-11-oasis-taxii21-p36-4', 0, 13, '11-oasis-taxii21', 'retrieved', '90472176EF929C38642D93505BADFC0CAAA6A3548E3D3F549901CBDD23F07B5D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
