INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p37-7', 'doc-11-oasis-taxii21', '', 37, 'Property Name Type Description id (required) string The identifier of the object that succeed, is pending, or failed to be created. For STIX objects the id MUST be the STIX Object id. For object types that do not have their own identifier, the server MAY use any value as the id.', 'kb-doc-11-oasis-taxii21-p37-7', 0, 51, '11-oasis-taxii21', 'retrieved', '63D3BDADA280BC619EDAE268112229E33BC01D654445E9BCC1F0917D5D5FA2FF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
