INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p37-8', 'doc-11-oasis-taxii21', '', 37, 'version (required) string The version of the object that succeeded, is pending, or failed to be created. For STIX objects the version MUST be the STIX modified timestamp Property. If a STIX object is not versioned (and therefore does not have a modified timestamp), the server MUST use the created timestamp. If the STIX object does not have a created or modified timestamp then the server SHOULD use a value for the version that is consistent to the server.', 'kb-doc-11-oasis-taxii21-p37-8', 0, 79, '11-oasis-taxii21', 'retrieved', '2800E645014381C1536EE532DCFEAA1B86F409D89CC8704029EAC2D06F6DD273', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
