VALUES ('doc-11-oasis-taxii21-p39-4', 'doc-11-oasis-taxii21', '', 39, 'URL Methods Resource Type {api-root}/collections/ GET collections {api-root}/collections/{id}/ GET collection {api-root}/collections/{id}/manifest/ GET manifest {api-root}/collections/{id}/objects/ GET, POST envelope {api-root}/collections/{id}/objects/{object-id}/ GET, DELETE envelope {api-root}/collections/{id}/objects/{object-id}/versions/ GET versions', 'kb-doc-11-oasis-taxii21-p39-4', 0, 24, '11-oasis-taxii21', 'retrieved', '621F13C998464EE6FF5A674F315761F685267DD413EA33974EF7139289DA69C4', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
