INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p39-5', 'doc-11-oasis-taxii21', '', 39, '5.1 Get Collections This Endpoint provides information about the Collections hosted under this API Root. This is similar to the response to get a Collection (see section 5.2), but rather than providing information about one Collection it provides information about all of the Collections. Most importantly, it provides the Collection''s id, which is used to request objects or manifest entries from the Collection.', 'kb-doc-11-oasis-taxii21-p39-5', 0, 63, '11-oasis-taxii21', 'retrieved', '9196A6EE8B7A68872EDDAEB26E7F68B79AEC85E45338A87D0E696419E5D1549E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
