INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p44-5', 'doc-11-oasis-taxii21', '', 44, 'alias (optional) string A human readable collection name that can be used on systems to alias a collection ID. This could be used by organizations that want to preconfigure a known collection of data, regardless of the underlying collection ID that is configured on a specific implementations.', 'kb-doc-11-oasis-taxii21-p44-5', 0, 47, '11-oasis-taxii21', 'retrieved', '33DC50E7213FB6BEF4549B7F808ADB61DFF843623C05254C3A354DCF40213323', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
