INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p44-6', 'doc-11-oasis-taxii21', '', 44, 'If defined, the alias MUST be unique within a single api-root on a single TAXII server. There is no guarantee that an alias is globally unique across api- roots or TAXII server instances.', 'kb-doc-11-oasis-taxii21-p44-6', 0, 33, '11-oasis-taxii21', 'retrieved', 'B189517A58865D6537948BA436725052F8B37CBDEA0AD793F4316374C8B0327B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
