INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p44-7', 'doc-11-oasis-taxii21', '', 44, 'Example: /{api-root}/collections/critical-high-value- indicators/ can_read (required) boolean Indicates if the requester can read (i.e., GET) objects from this Collection. If true, users are allowed to access the Get Objects, Get an Object, or Get Object Manifests endpoints for this Collection. If false, users are not allowed to access these endpoints.', 'kb-doc-11-oasis-taxii21-p44-7', 0, 49, '11-oasis-taxii21', 'retrieved', '0CC89112FD065A8D43C82E7DF958B5F05022092A40427BB42A7224C139172082', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
