INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p44-8', 'doc-11-oasis-taxii21', '', 44, 'can_write (required) boolean Indicates if the requester can write (i.e., POST) objects to this Collection. If true, users are allowed to access the Add Objects endpoint for this Collection. If false, users are not allowed to access this endpoint.', 'kb-doc-11-oasis-taxii21-p44-8', 0, 39, '11-oasis-taxii21', 'retrieved', 'AA9A6EAAFC9493E6200C0B199329838F94A01F4B52CA3029602AF0743BCB2C81', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
