INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p45-2', 'doc-11-oasis-taxii21', '', 45, '5.3 Get Object Manifests This Endpoint retrieves a manifest about the objects in a Collection. It supports filtering identical to the get objects Endpoint (see section 5.4) but rather than returning the object itself it returns metadata about the object. It can be used to retrieve metadata to decide whether it''s worth retrieving the actual objects.', 'kb-doc-11-oasis-taxii21-p45-2', 0, 56, '11-oasis-taxii21', 'retrieved', 'EB0C2A8FAC5E70C574C8FC2912CED86B20F9387A7A45EE5D0DA9AFAEB318BA72', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
