INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p45-4', 'doc-11-oasis-taxii21', '', 45, 'If the Collection specifies can_read as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error.', 'kb-doc-11-oasis-taxii21-p45-4', 0, 26, '11-oasis-taxii21', 'retrieved', 'FA579A3FEEE185F69365C5230EF4CDEF7AC814A8818DD657A9B52F4C81EF465A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
