INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p45-5', 'doc-11-oasis-taxii21', '', 45, 'Filtering is applied against the source object rather than the manifest entry for an obje ct. Thus, searching the manifest for a type of indicator will return the manifest entries for objects with a type of indicator, even though the manifest doesn''t have a type property.', 'kb-doc-11-oasis-taxii21-p45-5', 0, 46, '11-oasis-taxii21', 'retrieved', '0C9F211F89472CDD9B4A391FA7778D9E704A6281E5C0BD9699CE6FAE3E1A23C2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
