VALUES ('doc-11-oasis-taxii21-p45-11', 'doc-11-oasis-taxii21', '', 45, 'URL Filtering Parameters added_after - a single timestamp (e.g., ?added_after=...) limit - a single integer (e.g., ?limit=...) next - a single string (e.g., ?next=...) id - an id(s) of an object (e.g., ?match[id]=...) type - the type(s) of an object (e.g., ?match[type]=...) version - the version(s) of an object (e.g., ?match[version]=...) spec_version - the specification version(s) (e.g., ?match[spec_version]=...)', 'kb-doc-11-oasis-taxii21-p45-11', 0, 58, '11-oasis-taxii21', 'retrieved', '3D0A1CA448851D61C6B0ACA233EEFC3657E887E3566113387D0936CDFBA74B1A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
