INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p46-1', 'doc-11-oasis-taxii21', '', 46, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 46 of 79 Filtering is based on properties of the objects that the manifest entries represent. For example, filtering by type=indicator will return manifest entries for objects with a type of indicator.', 'kb-doc-11-oasis-taxii21-p46-1', 0, 49, '11-oasis-taxii21', 'retrieved', '454BFC3BE7CA0AE3CDB9F4831A976E48D8C23B4BFC32649ED75AA3DB861527F9', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
