VALUES ('doc-11-oasis-taxii21-p48-1', 'doc-11-oasis-taxii21', '', 48, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 48 of 79 the response is an empty object.', 'kb-doc-11-oasis-taxii21-p48-1', 0, 26, '11-oasis-taxii21', 'retrieved', '4EC6EB1C2C6B84034B53FE4C327D4E5D002EFFC35AB3C03E46E1CCE11E9CBEC5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
