INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-2', 'doc-11-oasis-taxii21', '', 48, 'Type Name: manifest-record The manifest-record type captures metadata about a single version of an object, indicated by the id property. The metadata includes information such as when that version of the object was added to the Collection, the version of the object itself, and the media type that this specific version of the object is available in.', 'kb-doc-11-oasis-taxii21-p48-2', 0, 57, '11-oasis-taxii21', 'retrieved', '4DB829091EF2876FD0C406AE1C6E19FBC9733B06C002C192E9E6AE2C266F0A54', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-3', 'doc-11-oasis-taxii21', '', 48, 'Property Name Type Description id (required) string The identifier of the object that this manifest entry describes. For STIX objects the id MUST be the STIX Object id. For object types that do not have their own identifier, the server MAY use any value as the id.', 'kb-doc-11-oasis-taxii21-p48-3', 0, 47, '11-oasis-taxii21', 'retrieved', '5BB12FDBCF503887CF9FF99519F690DBFB6E6B9A7024ACD11217AA20765776D3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-6', 'doc-11-oasis-taxii21', '', 48, 'For objects in STIX format, the STIX modified property is the version. If a STIX object is not versioned (and therefore does not have a modified timestamp), the server MUST use the created timestamp. If the STIX object does not have a created or modified timestamp then the server SHOULD use a value for the version that is consistent to the server.', 'kb-doc-11-oasis-taxii21-p48-6', 0, 62, '11-oasis-taxii21', 'retrieved', '3DB4101D7FDFB38D203DCAFC134E9ED02C7500BA8DA8B47B1CD6EFA74D969602', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-7', 'doc-11-oasis-taxii21', '', 48, 'media_type (optional) string The media type that this specific version of the object can be requested in. This value MUST be one of the media types listed on the collection resource.', 'kb-doc-11-oasis-taxii21-p48-7', 0, 31, '11-oasis-taxii21', 'retrieved', '4DA57BCD027CAD767FA09F5A4C3A904830F0368E247E62C806493F1CF1F55240', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
