INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-8', 'doc-11-oasis-taxii21', '', 48, '5.4 Get Objects This Endpoint retrieves objects from a Collection. Clients can search for objects in the Collection, retrieve all objects in a Collection, or paginate through objects in the Collection. Pagination is supported by the limit URL query parameter (see section 3.4) and the more property of the envelope (see section 3.7).', 'kb-doc-11-oasis-taxii21-p48-8', 0, 53, '11-oasis-taxii21', 'retrieved', '941619B9777BBBEF32645FE4AE13473F314C1A3B97FA6CCB324B53E157B7FA24', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-9', 'doc-11-oasis-taxii21', '', 48, 'If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found) If the Collection specifies can_read as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error.', 'kb-doc-11-oasis-taxii21-p48-9', 0, 47, '11-oasis-taxii21', 'retrieved', 'B40A498C8683409EF09866017217C489CE4DB50EC4A090417F867643B0C815E2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p48-10', 'doc-11-oasis-taxii21', '', 48, 'To support searching the Collection, this Endpoint supports filtering as defined in section 3.4. Clients can provide one or more filter parameters to get objects with a specific ID, of a specific type, or with a specific version. Future versions of TAXII will add more advanced filtering capabilities.', 'kb-doc-11-oasis-taxii21-p48-10', 0, 48, '11-oasis-taxii21', 'retrieved', '51A441CFDDF4D15E89C1D88A73DDBAFAF57C67D758EF34DF17C3E6A521F21EE4', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p49-1', 'doc-11-oasis-taxii21', '', 49, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 49 of 79 When requesting STIX 2 content, that content will always be delivered in a TAXII envelope even if there only one object returned. If no STIX objects are returned, the response MUST include an empty envelope. An envelope is returned even when requesting a specific object ID, as there may be multiple versions of that object that are returned.', 'kb-doc-11-oasis-taxii21-p49-1', 0, 78, '11-oasis-taxii21', 'retrieved', '7681B93A0E1E9861CC959B3F5FAC33B28AC820CDC55A0AC027AE51E0AF665A87', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
