VALUES ('doc-11-oasis-taxii21-p51-4', 'doc-11-oasis-taxii21', '', 51, 'If the Collection specifies can_write as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error.', 'kb-doc-11-oasis-taxii21-p51-4', 0, 26, '11-oasis-taxii21', 'retrieved', '7513DF5653B1D4D9F5381D00C02005B54F46020EE3A31C70D233DAF6947ABE9B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
