INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p51-5', 'doc-11-oasis-taxii21', '', 51, 'Successful responses to this Endpoint will contain a status resource describing the status of the request.', 'kb-doc-11-oasis-taxii21-p51-5', 0, 16, '11-oasis-taxii21', 'retrieved', '8ED0AD7B23AFDCADD5A52D22565B7EB43EA2A0CB6250A751FA14AE510ACB960D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
