INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p51-6', 'doc-11-oasis-taxii21', '', 51, 'The status resource contains an id, which can be used to make requests to the get status Endpoint (see section 4.3), a status flag to indicate whether the request is completed or still being processed, and information about the status of the particular objects in the request. If a client publishes an exact duplicate of an Object already present in the Collection, the server MUST not return an error for that Object.', 'kb-doc-11-oasis-taxii21-p51-6', 0, 72, '11-oasis-taxii21', 'retrieved', '40E456D163501DA5F1E0E770FC0171F1DC158FBDA215CE5904D02A87B1F492CD', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p51-7', 'doc-11-oasis-taxii21', '', 51, 'If the request is marked pending in the status property, the client SHOULD periodically poll the get status Endpoint to get an updated status until such a time that the status property returns a value of complete. At that point, the request can be considered complete.', 'kb-doc-11-oasis-taxii21-p51-7', 0, 46, '11-oasis-taxii21', 'retrieved', 'FA6120DA7344F61BD942CC3D0DF1FED7ADCF5089E136DEE964953FFFC1DBABBF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p51-8', 'doc-11-oasis-taxii21', '', 51, 'When adding STIX 2 content, clients MUST deliver all objects in a TAXII envelope.', 'kb-doc-11-oasis-taxii21-p51-8', 0, 14, '11-oasis-taxii21', 'retrieved', '1CF9C01E8CFC32B9EF466BD622E5BE736932D80C74F19E6A3E1A2B83357DE31B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
