VALUES ('doc-11-oasis-taxii21-p51-12', 'doc-11-oasis-taxii21', '', 51, 'URL Parameters {api-root} - the base URL of the API Root {id} - the identifier of the Collection where objects are being added', 'kb-doc-11-oasis-taxii21-p51-12', 0, 23, '11-oasis-taxii21', 'retrieved', 'D6F4EA4557B1D94CA93417A919E8B3A3707176138DD48631473A1DA11FC00585', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
