VALUES ('doc-11-oasis-taxii21-p52-6', 'doc-11-oasis-taxii21', '', 52, 'This can happen, for example, when sending a version of STIX that this TAXII Server does not support and cannot process, when sending a malformed body, or other unprocessable content', 'kb-doc-11-oasis-taxii21-p52-6', 0, 30, '11-oasis-taxii21', 'retrieved', 'CE0E0D92DA05C59507C9846FF2F5E3281BC2BCEB1BB85C34012C8A42CDEEDC44', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
