INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p53-5', 'doc-11-oasis-taxii21', '', 53, '5.6 Get an Object This Endpoint gets an object from a Collection by its id. It can be thought of as a search where the match[id] parameter is set to the {object-id} in the path. For STIX 2 objects, the {object-id} MUST be the STIX id.', 'kb-doc-11-oasis-taxii21-p53-5', 0, 46, '11-oasis-taxii21', 'retrieved', 'E9DC64E5A63E9E4A99CC130E163C3F5A9E288217E4DE8288E34943F5ACC15704', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
