INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p53-8', 'doc-11-oasis-taxii21', '', 53, 'To support getting a particular version of an object, this Endpoint supports filtering as defined in section 3.4. The only valid match parameter is version.', 'kb-doc-11-oasis-taxii21-p53-8', 0, 25, '11-oasis-taxii21', 'retrieved', '5CF515C60F2022C7FF18773F12F4CDAD07EB4FA8DF48B55014DBD187BAC6F7AA', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
