INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p53-9', 'doc-11-oasis-taxii21', '', 53, 'When requesting STIX 2 content, that content will always be delivered in a TAXII envelope even if there only one object returned. If no STIX objects are returned, the response MUST include an empty envelope. An envelope is returned even when requesting a specific object ID, as there may be multiple versions of that object that are returned.', 'kb-doc-11-oasis-taxii21-p53-9', 0, 58, '11-oasis-taxii21', 'retrieved', '2F68B5A5FD0961EEC3F5F5E68C3B33493F15BA61E50AD8FEC689FB4DFCBDC87D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
