INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p56-2', 'doc-11-oasis-taxii21', '', 56, 'To support removing a particular version of an object, this Endpoint supports filtering as defined in section 3.4. The only valid match parameter is version.', 'kb-doc-11-oasis-taxii21-p56-2', 0, 25, '11-oasis-taxii21', 'retrieved', 'DDC6337A68BA0EA5D6AEF96E45F359660EE87444DBC3F8A5C54A788BF0565DDB', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
