VALUES ('doc-11-oasis-taxii21-p56-6', 'doc-11-oasis-taxii21', '', 56, 'NOTE, the DELETE endpoint is only supported for collections where both can_read is true and can_write is true.', 'kb-doc-11-oasis-taxii21-p56-6', 0, 18, '11-oasis-taxii21', 'retrieved', 'BC1E63B15D4F011CE369FC265978355EA02FEEC02D5EDC1B33D728D5BAF69407', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
