INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p58-4', 'doc-11-oasis-taxii21', '', 58, '5.8 Get Object Versions This Endpoint retrieves a list of one or more versions of an object in a Collection. This list can be used to decide whether it''s worth retrieving the actual objects, or if new versions have been added. If a STIX object is not versioned (and therefore does not have a modified timestamp), the server MUST use created timestamp.', 'kb-doc-11-oasis-taxii21-p58-4', 0, 62, '11-oasis-taxii21', 'retrieved', 'B56D951D9AD1E0AF349389AD09B3A39A834E5B2635D646F906321147F0E7C839', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
