VALUES ('doc-11-oasis-taxii21-p60-6', 'doc-11-oasis-taxii21', '', 60, 'versions (optional) list of type string The list of object versions returned by the request. If there are no versions returned, this key MUST be omitted, and the response is an empty object.', 'kb-doc-11-oasis-taxii21-p60-6', 0, 33, '11-oasis-taxii21', 'retrieved', 'AFE1833B2253E434533679D8241AEDE083B44E15B16265FE933E926A7F7CA27D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
