INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-1', 'doc-11-oasis-taxii21', '', 62, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 62 of 79 7 Customizing TAXII Resources This section defines how to extend TAXII in an interoperable manner.', 'kb-doc-11-oasis-taxii21-p62-1', 0, 35, '11-oasis-taxii21', 'retrieved', '23C3F1BE756BB2AEA5697BE2CEC8DE6F7DCFC171003AFAE297384139B5F900B2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-2', 'doc-11-oasis-taxii21', '', 62, '7.1 Custom Properties It is understood that there will be cases where certain information exchanges can be improved by adding properties that are not specified nor reserved in this document; these properties are called Custom Properties. This section provides guidance and requirements for how TAXII Servers and Clients should use and interpret Custom Properties in order to extend TAXII in an interoperable manner.', 'kb-doc-11-oasis-taxii21-p62-2', 0, 63, '11-oasis-taxii21', 'retrieved', '161374F24AB50AF9E41E40A0F60A56DC6DC2DF576E4C446D7B7D4F09B6F0D680', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-3', 'doc-11-oasis-taxii21', '', 62, 'Note: The presence of Custom Properties may introduce variability of behavior depending on whether or not the TAXII Server or Client understands the Custom Properties. A reasonable strategy to minimize unwanted variations in behavior is to provide well defined and consistent rules for processing Custom Properties to any TAXII Server or Client that would be reasonably expected to parse them.', 'kb-doc-11-oasis-taxii21-p62-3', 0, 60, '11-oasis-taxii21', 'retrieved', '7108D9270A91A859FACE652DD603657EB606689E60AA9C7AAE854F695E3C280E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-5', 'doc-11-oasis-taxii21', '', 62, '● Custom Property names MUST be in ASCII and MUST only contain the characters a–z (lowercase ASCII), 0–9, and underscore (_).', 'kb-doc-11-oasis-taxii21-p62-5', 0, 21, '11-oasis-taxii21', 'retrieved', 'A01FF884A6897B2111B311ED62DEAE09142029A5F72AFB1B8D0F5BBC09B10C09', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-6', 'doc-11-oasis-taxii21', '', 62, '● Custom Property names SHOULD start with “x_” followed by a source unique identifier (such as a domain name with dots replaced by underscores), an underscore and then the name. For example, x_example_com_customfield.', 'kb-doc-11-oasis-taxii21-p62-6', 0, 33, '11-oasis-taxii21', 'retrieved', '9611ADC53E77D814973AD0CFB8B57B4E495C3D809E76916A528739B579B71C93', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-9', 'doc-11-oasis-taxii21', '', 62, '● Custom Property names that are not prefixed with “x_” may be used in a future version of the specification for a different meaning. If compatibility with future versions of this specifi cation is required, the “x_” prefix MUST be used.', 'kb-doc-11-oasis-taxii21-p62-9', 0, 41, '11-oasis-taxii21', 'retrieved', '41E5C4EB36704ABDFF661A3D365D39E0162A8718665D6ADC1FAD5CACF14FFDF5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-10', 'doc-11-oasis-taxii21', '', 62, '● Custom Properties SHOULD only be used when there are no existing properties defined by the TAXII specification that fulfill that need.', 'kb-doc-11-oasis-taxii21-p62-10', 0, 22, '11-oasis-taxii21', 'retrieved', 'A1DED73F7B837A44CE00C4493551F913015B77BF5AD438105A86C35DD43701D3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-11', 'doc-11-oasis-taxii21', '', 62, 'TAXII Servers that receive a TAXII Resource with one or more Custom Properties it does not understand MAY respond in one of two ways: 1. Either refuse to process the content further and respond to the message with an HTTP 422 (Unprocessable Entity) status code, 2. or silently ignore non-understood properties and continue processing the message.', 'kb-doc-11-oasis-taxii21-p62-11', 0, 56, '11-oasis-taxii21', 'retrieved', 'DEA12DE68F9A6BEF515C714893619B78D29263F03A2DE9B91BC33EB0342B9477', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-12', 'doc-11-oasis-taxii21', '', 62, 'TAXII Clients that receive a TAXII Resource with one or more Custom Properties it does not understand MAY silently ignore non-understood properties and continue processing the message.', 'kb-doc-11-oasis-taxii21-p62-12', 0, 27, '11-oasis-taxii21', 'retrieved', '83A00B6197AD83E477F685A1825427BAEAEDAA85A491FF56E24AD4587A28CDDD', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
