INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p62-13', 'doc-11-oasis-taxii21', '', 62, 'The reporting and logging of errors originating from the processing of Custom Properties depends on the TAXII Server and Client implementations and is therefore not covered in this specification.', 'kb-doc-11-oasis-taxii21-p62-13', 0, 29, '11-oasis-taxii21', 'retrieved', '07F7320CED13E812BDCE6620B4B7ECFF2D9F0DE8DEC50F668DD697195BB29737', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
