VALUES ('doc-11-oasis-taxii21-p64-7', 'doc-11-oasis-taxii21', '', 64, '8.2 Mandatory Server Features This section defines the mandatory features that all TAXII Servers must implement.', 'kb-doc-11-oasis-taxii21-p64-7', 0, 16, '11-oasis-taxii21', 'retrieved', 'ABD524CEBE371D050F7F4A17F79798ACBD2FCB89F1E9A74E078833082D76ED67', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
