VALUES ('doc-11-oasis-taxii21-p64-14', 'doc-11-oasis-taxii21', '', 64, '8.2.2 HTTPS and Authentication Server Requirements 1. It MUST accept TAXII 2.1 requests using HTTPS [RFC7230].', 'kb-doc-11-oasis-taxii21-p64-14', 0, 16, '11-oasis-taxii21', 'retrieved', '2D422BC56DEA4F47873791436E72B0711B868537A69CF255EF2EAF27117A0096', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
