VALUES ('doc-11-oasis-taxii21-p65-6', 'doc-11-oasis-taxii21', '', 65, '8.3.1 Client Certificate Verification TAXII 2.1 servers MAY choose to verify a client’s certificate and use it for authentication. TAXII Servers supporting client certificate verification and authentication MUST follow the normative requirements listed in this section.', 'kb-doc-11-oasis-taxii21-p65-6', 0, 36, '11-oasis-taxii21', 'retrieved', '7BA40046FF5DFB60E33201AC48A65DA111462593FD26499867DF18D5B15D152C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
