VALUES ('doc-11-oasis-taxii21-p65-7', 'doc-11-oasis-taxii21', '', 65, '● The default strategy for TAXII Servers authenticating and verifying certificates SHOULD be PKIX as defined in [RFC5280], [RFC6818], [RFC6125] et al.', 'kb-doc-11-oasis-taxii21-p65-7', 0, 22, '11-oasis-taxii21', 'retrieved', '81FEA90F61AD90F6E60551E2732B182448D76E1574E27118B0B42BA26CB4AF5B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
