VALUES ('doc-11-oasis-taxii21-p65-8', 'doc-11-oasis-taxii21', '', 65, '● It MAY support other certificate verification policies such as Certificate Pinning.', 'kb-doc-11-oasis-taxii21-p65-8', 0, 12, '11-oasis-taxii21', 'retrieved', '5E720D480B19C6E5A1F242D6D823F4210121C6947D131E864C6ACA9356165CFF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
