VALUES ('doc-11-oasis-taxii21-p65-9', 'doc-11-oasis-taxii21', '', 65, '8.4 TAXII Clients This section describes the types of TAXII Clients that can be implemented and which normative requirements those types of clients must conform to.', 'kb-doc-11-oasis-taxii21-p65-9', 0, 26, '11-oasis-taxii21', 'retrieved', '1D1643AD7B67B664F228E477F1C83DAFE66A4E0A11AFFDD35F62B9E48927B536', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
