VALUES ('doc-11-oasis-taxii21-p65-10', 'doc-11-oasis-taxii21', '', 65, '8.4.1 TAXII 2.1 Client A "TAXII 2.1 Client" is any software that conforms to the following normative requirements: 1. It MUST support all requirements for a TAXII Collections Client as defined in section 8.4.2.', 'kb-doc-11-oasis-taxii21-p65-10', 0, 34, '11-oasis-taxii21', 'retrieved', '730AAEE53C0425E5973B18963F001B65047CBEC1DB243A66B5C835F66BB63235', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
