VALUES ('doc-11-oasis-taxii21-p65-15', 'doc-11-oasis-taxii21', '', 65, '8.5 Mandatory Client Features This section defines the mandatory features that all TAXII Clients MUST support.', 'kb-doc-11-oasis-taxii21-p65-15', 0, 16, '11-oasis-taxii21', 'retrieved', '428181D740615F733E13EBB9A3795B27575595C8A8BBCDC94A227800F1FE94F1', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
