VALUES ('doc-11-oasis-taxii21-p65-16', 'doc-11-oasis-taxii21', '', 65, '8.5.1 HTTPS and Authentication Client Requirements 1. It MUST initiate TAXII 2.1 requests to a TAXII 2.1 Server using HTTPS [RFC7230].', 'kb-doc-11-oasis-taxii21-p65-16', 0, 21, '11-oasis-taxii21', 'retrieved', 'A51AF9406418B99C2A550AFCD9E2714DD0F0DB0F4E15E1C493E32AD85CF45A78', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
