INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p65-17', 'doc-11-oasis-taxii21', '', 65, '2. It MUST support TLS 1.2 and SHOULD use TLS version 1.3 [RFC8446] or higher 3. It SHOULD NOT use TLS 1.2 with any of the cipher suites that are listed in the cipher suite blacklist in Appendix A of [RFC7540].', 'kb-doc-11-oasis-taxii21-p65-17', 0, 41, '11-oasis-taxii21', 'retrieved', 'CCA33AE2322C6B2516B28D543A462CF2D14713F9E64CDB070AB2A3DC6FC783BB', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
