VALUES ('doc-11-oasis-taxii21-p65-18', 'doc-11-oasis-taxii21', '', 65, '4. It MUST implement the HTTP Basic authentication scheme as a client per [RFC 7617].', 'kb-doc-11-oasis-taxii21-p65-18', 0, 15, '11-oasis-taxii21', 'retrieved', 'D231FE8525A94526E65D906F4BE24C164B903A6EEC2CC06A403E5B1B7905DF10', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
