VALUES ('doc-11-oasis-taxii21-p66-3', 'doc-11-oasis-taxii21', '', 66, '● TAXII Clients MAY support other certification verification policies such as: ○ Certificate Pinning: A single or limited set of either hard-coded or physically distributed pinned certificate authorities or end-entity certificates.', 'kb-doc-11-oasis-taxii21-p66-3', 0, 31, '11-oasis-taxii21', 'retrieved', '83B3C3F14B19D0A765FF248EF8BB22ED86FCB33D54270653B6835F26A8C5BC38', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
