INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p68-2', 'doc-11-oasis-taxii21', '', 68, 'This appendix contains the required information to register the TAXII media type with IANA. While some of the information here is only for IANA, implementers of TAXII should pay close attention to the security considerations and privacy considerations outlined in this appendix.', 'kb-doc-11-oasis-taxii21-p68-2', 0, 42, '11-oasis-taxii21', 'retrieved', 'C48D8A726CA5B4B07551326C63129CAE0BF9DBA92B6B61545C612D5F8551D1D6', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
