INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p68-7', 'doc-11-oasis-taxii21', '', 68, 'Optional parameters: version This parameter is used to designate the specification version of TAXII that is being used during HTTP content negotiation. Example: "application/taxii+json;version=2.1". The parameter value is of the form ''n.m'', where n is the major version and m the minor version, both unsigned integer values.', 'kb-doc-11-oasis-taxii21-p68-7', 0, 47, '11-oasis-taxii21', 'retrieved', 'F072CE4475829378B679EC9F3883A0B0464ABA9D8E0FC30196EA8A23EE97C4B5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p68-8', 'doc-11-oasis-taxii21', '', 68, 'Encoding considerations: binary Encoding considerations are identical to those specified for the "application/json" media type. See [RFC8259].', 'kb-doc-11-oasis-taxii21-p68-8', 0, 17, '11-oasis-taxii21', 'retrieved', '5A19E285BA68CBF69B278CF49D98E02FB517E25C579DAA64C27F612DFD8C4588', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
