VALUES ('doc-11-oasis-taxii21-p68-9', 'doc-11-oasis-taxii21', '', 68, 'Security considerations: These considerations are, in part, derived from Section 9 of the Resource-Oriented Lightweight Information Exchange [RFC8322].', 'kb-doc-11-oasis-taxii21-p68-9', 0, 18, '11-oasis-taxii21', 'retrieved', '57D1B92AF6C293180B78510987773756BAAFE11801EB8A72B0371918FB311DE0', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
