VALUES ('doc-11-oasis-taxii21-p68-10', 'doc-11-oasis-taxii21', '', 68, 'This document defines a resource-oriented approach for exchanging cyber threat intelligence using HTTP [RFC7230] over TLS [RFC5246] and the JSON [RFC8259] Format.', 'kb-doc-11-oasis-taxii21-p68-10', 0, 22, '11-oasis-taxii21', 'retrieved', 'AD5A68F4A12CA100BBD6CD36D1B68BD7B20C9A48E72F44D4ABB267082A77E6AC', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
