VALUES ('doc-11-oasis-taxii21-p68-11', 'doc-11-oasis-taxii21', '', 68, 'As such, implementers must understand the security considerations described in those specifications.', 'kb-doc-11-oasis-taxii21-p68-11', 0, 12, '11-oasis-taxii21', 'retrieved', '03314BE5CDE319CEA0CB8D38D1483430E0849B27CEE1033405372FCD00B5BAAE', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
