VALUES ('doc-11-oasis-taxii21-p68-12', 'doc-11-oasis-taxii21', '', 68, 'Security considerations relating to the generation and consumption of TAXII messages are similar to application/json and are discussed in Section 12 of [RFC8259].', 'kb-doc-11-oasis-taxii21-p68-12', 0, 23, '11-oasis-taxii21', 'retrieved', '1666DC70604E03B689D48E0D7E0078A58E6C4B2EC36C452E6A4F19264FF06E9C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
