INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p68-13', 'doc-11-oasis-taxii21', '', 68, 'The discovery API contains one or multiple URLs, therefor the security considerations stated in Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and attempts of path traversal.', 'kb-doc-11-oasis-taxii21-p68-13', 0, 33, '11-oasis-taxii21', 'retrieved', '47EAA9D1B5997A177727402DEC124160E7164721BA64B49897CBA859E7029CF0', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p68-14', 'doc-11-oasis-taxii21', '', 68, 'Documents of "application/taxii+json" are simply request and response messages for an RPC like mechanism for searching, uploading and downloading Cyber Threat Intelligence (CTI) documents, most commonly STIX. The documents only contain metadata about the TAXII server, such as descriptions, versions of CTI or status response of the request. Documents do not contain active or executable content.', 'kb-doc-11-oasis-taxii21-p68-14', 0, 56, '11-oasis-taxii21', 'retrieved', 'F3B65B336C4ECF491BEF74AAB495FE7E40D477A3D8997B9145C50EED1A48EF0D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-1', 'doc-11-oasis-taxii21', '', 69, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 69 of 79 Unicode is used to represent text such as descriptions in the format. The considerations documented by Unicode Technical Report #36: Unicode Security Considerations [ UNICODE] should be taken into account.', 'kb-doc-11-oasis-taxii21-p69-1', 0, 50, '11-oasis-taxii21', 'retrieved', '1A21C536EFE487AE5F9C8AC809DE96267927218F54922F5F7BCB94D79B7F637E', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-2', 'doc-11-oasis-taxii21', '', 69, 'To protect the confidentiality of a given resource provided by a TAXII implementation, requests for retrieval of a resource need to be authenticated to prevent unauthorized users from accessing the resource. It can also be useful to log and audit access to sensitive resources to verify that proper access controls remain in place over time.', 'kb-doc-11-oasis-taxii21-p69-2', 0, 55, '11-oasis-taxii21', 'retrieved', '5E0A18DA9465BB9A45106826583E876671FEFC53C40EE90364FC5445660FA81C', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-3', 'doc-11-oasis-taxii21', '', 69, 'Access control to content made available using TAXII should use mechanisms that are appropriate to the sensitivity of the information. While the primitive authentication mechanism of HTTP Basic Authentication [RFC7617] is mandatory to implement for base level interoperability it is rarely appropriate for sensitive information.', 'kb-doc-11-oasis-taxii21-p69-3', 0, 45, '11-oasis-taxii21', 'retrieved', 'CC0AE8446FD52443EAD4C049F308D48A02941778C824FD266B7F2F5DF75CBEB9', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-4', 'doc-11-oasis-taxii21', '', 69, 'A number of authentication schemes are defined in the "HTTP Authentication Schemes" registry at IANA [IANA AUTH].', 'kb-doc-11-oasis-taxii21-p69-4', 0, 17, '11-oasis-taxii21', 'retrieved', '80A43487F1B685BE044F0DED5F728DC8A7F05FCA250F5372A6873BC0CFCF5FF5', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-5', 'doc-11-oasis-taxii21', '', 69, 'Of these, HTTP Origin- Bound Authentication (HOBA) [RFC7486] and SCRAM-SHA-256 [RFC7804] ("SCRAM" stands for "Salted Challenge Response Authentication Mechanism") provide improved security properties over HTTP Basic [RFC7617] and Digest [RFC7616] authentication schemes. However, sharing communities that are engaged in sensitive collaborative analysis and/or operational response for indicators and incidents targeting high-value information systems should adopt a suitably stronger user authentication solution, such as a risk-based or multi-factor approach.', 'kb-doc-11-oasis-taxii21-p69-5', 0, 68, '11-oasis-taxii21', 'retrieved', '138F06C72090C631F39A577C95895E704DAD09C4C72A7D2E1AAC38DBE81AE6BE', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-6', 'doc-11-oasis-taxii21', '', 69, 'Collaborating consortiums may benefit from the adoption of a federated identity solution, such as those based upon OAuth [RFC6749] with the JSON Web Token (JWT) [RFC7797], or SAML-core [SAML-core] ("SAML" stands for "Security Assertion Markup Language"), SAML-bind [SAML- bind], and SAML-prof [SAML-prof] for web-based authentication and cross-organizational single sign-on.', 'kb-doc-11-oasis-taxii21-p69-6', 0, 49, '11-oasis-taxii21', 'retrieved', '99D4F5B71C3C2EA05C9C5E62C9D73F738D28BEEBA91B7336029F2F4B3C6CAFC4', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-7', 'doc-11-oasis-taxii21', '', 69, 'Dependency on a trusted third-party identity provider implies that appropriate care must be exercised to sufficiently secure the identity provider.', 'kb-doc-11-oasis-taxii21-p69-7', 0, 20, '11-oasis-taxii21', 'retrieved', '091DE76109E42104D2B58E2E41A68BF40DB166D1A81A57B31DDF15C462E34348', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-8', 'doc-11-oasis-taxii21', '', 69, 'Any attacks on the federated identity system would present a risk to the consortium, as a relying party. Potential mitigations include deployment of a federation-aware identity provider that is under the control of the information- sharing consortium, with suitably stringent technical and management controls.', 'kb-doc-11-oasis-taxii21-p69-8', 0, 44, '11-oasis-taxii21', 'retrieved', '293BD4438D1F5FB61BF5535B089418DBCA54D4C4FC7290426B1576B02D66E7F3', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-9', 'doc-11-oasis-taxii21', '', 69, 'It is recommended that all TAXII servers authenticate and authorize access to all collection data on a per-client basis using robust security methods. While this specification defines HTTP Basic as a minimum suggested authentication mechanism, more advanced security authentication methods are recommended when products or deployments require stronger authentication and authorization frameworks for accessing or posting data to the TAXII server.', 'kb-doc-11-oasis-taxii21-p69-9', 0, 61, '11-oasis-taxii21', 'retrieved', '59C7CED507ACF913D12FA141E23434A3A1B90BCA2039B300EAB214333DE1F67D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-10', 'doc-11-oasis-taxii21', '', 69, 'Authorization of resource representations is the responsibility of the source system, i.e., based on the authenticated user identity associated with an HTTP(S) request.', 'kb-doc-11-oasis-taxii21-p69-10', 0, 23, '11-oasis-taxii21', 'retrieved', '072DC8DD19B00E5D24DDC4870C20D36088C0805CFB43963AB6382FF374E7F0DD', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-11', 'doc-11-oasis-taxii21', '', 69, 'The required authorization policies that are to be enforced must therefore be managed by the security administrators of the source system.', 'kb-doc-11-oasis-taxii21-p69-11', 0, 21, '11-oasis-taxii21', 'retrieved', 'F92B8907219C0B7C02A85718D09A2026BE10EC278D912E86D3645D444FE27673', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-12', 'doc-11-oasis-taxii21', '', 69, 'Various authorization architectures would be suitable for this purpose, such as Role-Based Access Control (RBAC) [NIST RBAC] and/or Attribute-Based Access Control (ABAC), as embodied in the eXtensible Access Control Markup Language (XACML) [XACML].', 'kb-doc-11-oasis-taxii21-p69-12', 0, 33, '11-oasis-taxii21', 'retrieved', 'C9094F1BF36939224FC55FBF2777053D000EC3000C43225ADD6F0641AD43A498', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-13', 'doc-11-oasis-taxii21', '', 69, 'In particular, implementers adopting XACML may benefit from the capability to represent their authorization policies in a standardized, interoperable format.', 'kb-doc-11-oasis-taxii21-p69-13', 0, 20, '11-oasis-taxii21', 'retrieved', 'BA9ED73165C98A11B486AB0CD44BA4028305A3D723E2AA6191F370C889C9A58B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-14', 'doc-11-oasis-taxii21', '', 69, 'Note that implementers are free to choose any suitable authorization mechanism that is capable of fulfilling the policy enforcement requirements relevant to their consortium and/or organization.', 'kb-doc-11-oasis-taxii21-p69-14', 0, 26, '11-oasis-taxii21', 'retrieved', '270255D6B50E3F7D4D907C96E7BEBD2BBB3712B08D4F6731F472DC2A19EE58DE', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p69-15', 'doc-11-oasis-taxii21', '', 69, 'While the authentication and confidentiality for the TAXII session is done at a lower level via the transport mechanism (HTTPS), this does not obviate the consumer (server or client) from validating the format and contents of the documents sent in a session. This validation sh ould includes checking various limits, such as document size limits, to limit the risk of the other party attempting to attack the service.', 'kb-doc-11-oasis-taxii21-p69-15', 0, 68, '11-oasis-taxii21', 'retrieved', '7658B398D8BF926A791F4501835ECF02DF00EBA3300BE87BCB6E5EB60801646A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-1', 'doc-11-oasis-taxii21', '', 70, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 70 of 79', 'kb-doc-11-oasis-taxii21-p70-1', 0, 20, '11-oasis-taxii21', 'retrieved', '3C89373F04F488066EBA5A6F013E23E721FF2690016AA270A81B0EC58379FEC0', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-2', 'doc-11-oasis-taxii21', '', 70, 'Additional security requirements such as enforcing message-level security at the destination system could supplement the security enforcements performed at the source system; however, these destination-provided policy enforcements are out of scope for this specification.', 'kb-doc-11-oasis-taxii21-p70-2', 0, 34, '11-oasis-taxii21', 'retrieved', 'BCDF19A215ADA444E39EE69C30F8A583222C765502AA04B2993D4977B009422B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-3', 'doc-11-oasis-taxii21', '', 70, 'Implementers requiring this capability should consider leveraging, for example, the element in the RID schema. Refer to Section 9 of [RFC6545] for more information. Additionally, the underlying JSON serialization used in the representation can offer encryption and message authentication capabilities. For example, JSON Web Encryption [RFC7516] and JSON Web Signature [RFC7515], can provide such mechanisms.', 'kb-doc-11-oasis-taxii21-p70-3', 0, 55, '11-oasis-taxii21', 'retrieved', '4F9DEC2ADEA05068901D87A2160FE0A88D767D0781EF4FB510C9B3260719837B', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-4', 'doc-11-oasis-taxii21', '', 70, 'TAXII Servers may manage response volume in different ways. Implementers should be aware that a search request may return more objects than is prudent to return in a single HTTP Response. To mitigate this, TAXII servers should consider implementing restrictions on the number of objects it will return in a single HTTP response.', 'kb-doc-11-oasis-taxii21-p70-4', 0, 53, '11-oasis-taxii21', 'retrieved', '45C11362AAE4CCBAD78BA94CA5000D9E5037C4669FA35F54554C2B7BB3D1DBF2', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-5', 'doc-11-oasis-taxii21', '', 70, 'TAXII provides clients a rich set of filtering and query options to return specific results from repositories of CTI data. As such, TAXII servers should implement protections against queries that can potentially consume a significant amount of resources and prevent the server from functioning in a normal way.', 'kb-doc-11-oasis-taxii21-p70-5', 0, 48, '11-oasis-taxii21', 'retrieved', '025363047856CE6B38CC401389177C1E849061256CC6BDCDAAD16E44BC03BD36', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-6', 'doc-11-oasis-taxii21', '', 70, 'TAXII defines an optional error message that may contain sensitive application data.', 'kb-doc-11-oasis-taxii21-p70-6', 0, 12, '11-oasis-taxii21', 'retrieved', 'E282E25B877B816A53BEE58D723A2171F4D0D105C71DA32856A3A3D736547090', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-7', 'doc-11-oasis-taxii21', '', 70, 'Implementers should ensure that they do not leak descriptive text or application return codes for things that a user may not have access to, for example leak info about existence of something, implementation of something, vs. just not having access.', 'kb-doc-11-oasis-taxii21-p70-7', 0, 40, '11-oasis-taxii21', 'retrieved', 'E5447CD31686AD28DA0B79C3455B45CEA58D78575E3974E5F6D50D67705776F7', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
