INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-8', 'doc-11-oasis-taxii21', '', 70, 'Note: Despite TAXII searching and returning STIX objects, this format does not encapsulate any CTI content. It is expected that CTI documents will be sent with the appropriate mime -type. For these, consult their own security consideration sections.', 'kb-doc-11-oasis-taxii21-p70-8', 0, 38, '11-oasis-taxii21', 'retrieved', '434B5AB15BC5F33F605CAF3B50F9FDB7D4B023178F11D493420DDF4051276929', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-9', 'doc-11-oasis-taxii21', '', 70, 'As the next URL parameter is a client provided property, care must be taken that it is not blindly trusted as the same value that the server returned as part of the TAXII Envelope. This means it MUST NOT be implicitly trusted, and the value MUST be reevaluated in the context of the provided query such that incorrect data (data that the client is not authorized to have or not part of the query set) is not returned.', 'kb-doc-11-oasis-taxii21-p70-9', 0, 78, '11-oasis-taxii21', 'retrieved', 'C9F9CF1768EE8A5947DA3D6EE16A52C8BF885509299B75F9EAB0FA3286E7180A', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-10', 'doc-11-oasis-taxii21', '', 70, 'Privacy considerations These considerations are, in part, derived from Section 10 of the Resource-Oriented Lightweight Information Exchange [RFC8322].', 'kb-doc-11-oasis-taxii21-p70-10', 0, 18, '11-oasis-taxii21', 'retrieved', '538525E6BCB916E754D72EAC9B7FFE83726162BD2B39CEBF9543FB137C67CE12', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-11', 'doc-11-oasis-taxii21', '', 70, 'The documents contain various descriptions and other text. There is no expectation that these will contain private information, but as some may be user provided, there is no guarantee that a user will not inadvertently include private data. It is expected that the client or server authenticate the other party through the transport mechanism before sending any possible private data. As the protocol is about sharing data, it is expected that the parties understand their obligations in keeping relevant data private.', 'kb-doc-11-oasis-taxii21-p70-11', 0, 81, '11-oasis-taxii21', 'retrieved', 'E646C36171C99A2702D49CE329FAC3CD3365FDB659EDF3D9F8610325CDD1F586', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-12', 'doc-11-oasis-taxii21', '', 70, 'Adoption of the information-sharing approach described in this document will enable users to more easily perform correlations across separate, and potentially unrelated, cybersecurity information providers.', 'kb-doc-11-oasis-taxii21-p70-12', 0, 25, '11-oasis-taxii21', 'retrieved', 'DB18940A1C07DD370F5CBE86EC953559C7CD1580BBEA0B648BA196708E54AF9F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-13', 'doc-11-oasis-taxii21', '', 70, 'A client may succeed in assembling a data set that would not have been permitted within the context of the authorization policies of either provider when considered individually.', 'kb-doc-11-oasis-taxii21-p70-13', 0, 28, '11-oasis-taxii21', 'retrieved', '9C0E7F8D4158AEEBC8B8E6A54E45F8DBFCA1A47ED118A551EDAE4D776A538BED', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p70-14', 'doc-11-oasis-taxii21', '', 70, 'Thus, providers may face a risk of an attacker obtaining an access that const itutes', 'kb-doc-11-oasis-taxii21-p70-14', 0, 15, '11-oasis-taxii21', 'retrieved', '3CB7A8B459A73755A2088191C1E2D0ECB864B037529F5F6FB97F25F3A4B37405', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p71-1', 'doc-11-oasis-taxii21', '', 71, 'taxii-v2.1-os 10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 71 of 79 an undetected separation of duties (SOD) violation. It is important to note that this risk is not unique to this specification, and a similar potential for abuse exists with any other cybersecurity information-sharing protocol.', 'kb-doc-11-oasis-taxii21-p71-1', 0, 54, '11-oasis-taxii21', 'retrieved', 'B48F0FF931B9506BDEBA398151F1FDE9AFD3A18538369BB677B43AD6FA10AA86', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p71-2', 'doc-11-oasis-taxii21', '', 71, 'However, the wide availability of tools for HTTP clients implies that the resources and technical skills required for a successful exploit may be less than it was previously.', 'kb-doc-11-oasis-taxii21-p71-2', 0, 28, '11-oasis-taxii21', 'retrieved', '73B0605E11D21EAB3BDA06599366D9280B54DB3B0288BD0E50A856502B066841', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
