INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p71-3', 'doc-11-oasis-taxii21', '', 71, 'This risk can be best mitigated through appropriate vetting of the client at the time of account provisioning.', 'kb-doc-11-oasis-taxii21-p71-3', 0, 18, '11-oasis-taxii21', 'retrieved', '7D5AE1A0A3A487C3D9011648DC522ADA4B8CF22F451E230F5080E53AF6A81350', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p71-4', 'doc-11-oasis-taxii21', '', 71, 'In addition, any increase in the risk of this type of abuse should be offset by the corresponding increase in effectiveness that this specification affords to the defenders.', 'kb-doc-11-oasis-taxii21-p71-4', 0, 28, '11-oasis-taxii21', 'retrieved', '5CB3D409F31DAEE5DADE103EBF140AAD8EC37BDA02D3635236C7AE8CC9D69E83', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
