INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p71-5', 'doc-11-oasis-taxii21', '', 71, 'Overall, privacy concerns in TAXII can be mitigated by following security considerations and by the careful use of the content exchanged via TAXII.', 'kb-doc-11-oasis-taxii21-p71-5', 0, 23, '11-oasis-taxii21', 'retrieved', 'E5745DF40ADDCC1A6B8FCBD43137C19FA1CCE91F2025D7905CD7D69B474AE5AF', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p71-6', 'doc-11-oasis-taxii21', '', 71, 'Interoperability considerations: The TAXII specification specifies the format of conforming messages and the interpretation thereof. In addition, the OASIS Cyber Threat Intelligence (CTI) Technical Committee has defined interoperability tests to ensure conforming products and solutions can exchange TAXII documents.', 'kb-doc-11-oasis-taxii21-p71-6', 0, 39, '11-oasis-taxii21', 'retrieved', '518A02BE3322E499C1FA0D859009C69502371061C0587220F796678D149E828F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
