VALUES ('doc-11-oasis-taxii21-p71-7', 'doc-11-oasis-taxii21', '', 71, 'Published specification: TAXII Version 2.1 OASIS Committee Specification 01 http://docs.oasis-open.org/cti/taxii/v2.1/cs01/taxii-v2.1-cs01.html Cited in the "OASIS Standards" document: https://www.oasis-open.org/standards#oasiscommiteespecs, from https://www.oasis-open.org/standards#taxii2.1', 'kb-doc-11-oasis-taxii21-p71-7', 0, 19, '11-oasis-taxii21', 'retrieved', 'C577E9D085E70976031B4A145BFA5D39E3FEF83AC4F03CF7F07911B3421AD544', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
