VALUES ('doc-11-oasis-taxii21-p71-8', 'doc-11-oasis-taxii21', '', 71, 'Applications which use this media: TAXII is an application layer protocol for the communication of cyber threat information including STIX in a simple and scalable manner.', 'kb-doc-11-oasis-taxii21-p71-8', 0, 26, '11-oasis-taxii21', 'retrieved', '06033BDA6EA60F9768E2AC7BB016EE77717AAF3AD23E103A7199C716455BB14D', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
