VALUES ('doc-11-oasis-taxii21-p78-3', 'doc-11-oasis-taxii21', '', 78, 'GitHub Issues: 1, 8, 9, 10, 11, 12, 17, 18, 19, 20, 21, 23, 25, 26, 28, 29, 30, 31, 34, 35, 36, 39, 41, 43, 48, 49, 51, 53, 54, 56, 57, 62, 63 02 2018-05-18 Bret Jordan Drew Varner Fix typos, add clarifying text in some cases, changed DNS SRV record name, changed status resource, and made other minor changes.', 'kb-doc-11-oasis-taxii21-p78-3', 0, 62, '11-oasis-taxii21', 'retrieved', '4E031939457FDFB25171DDE672FA00B1CBC75B354A649C8251796436F4553797', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
