VALUES ('doc-11-oasis-taxii21-p78-4', 'doc-11-oasis-taxii21', '', 78, 'GitHub Issues: 47, 65, 66, 67, 70, 73, 74, 75 03 2018-07-12 Bret Jordan Drew Varner Reformatted the endpoint definitions, added an endpoint to DELETE an object, and added a versions endpoint to object by ID. Added IANA Considerations Appendix. Changed angle brackets "<>" in the URL parameters to be curly brackets "{}" to better align with API documentation best practices.', 'kb-doc-11-oasis-taxii21-p78-4', 0, 61, '11-oasis-taxii21', 'retrieved', '370F6D4871C34A963F2D482B22721771297E1C9A845C6B21B25674FF7757B2A9', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
