INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-11-oasis-taxii21-p78-6', 'doc-11-oasis-taxii21', '', 78, 'GitHub Issues: 37, 38, 58, 76, 78, 79, 80, 82, 84 04 2018-11-16 Bret Jordan Drew Varner Renamed resource subtype manifest- entry to manifest-record. Added clarifying text for each endpoint on error codes to be returned. Removed the STIX media type and STIX Bundle and replaced it with a TAXII Envelope. Added a limit URL parameter and a spec_versions match filter parameter. Added clarifying text around TAXII timestamps needing microsecond precision. Cleaned up text and deemphasized content other than STIX.', 'kb-doc-11-oasis-taxii21-p78-6', 0, 80, '11-oasis-taxii21', 'retrieved', '9C120AAAC9A79AB0EA99779788DEC99CF107B35626A90F9AF38F872AFCB3359F', 'v1', '{"source_id": "11-oasis-taxii21", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
