INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-12-nist-ai-rmf-p2-1', 'doc-12-nist-ai-rmf', '', 2, 'NIST AI 100-1 Artificial Intelligence Risk Management Framework (AI RMF 1.0) This publication is available free of charge from: https://doi.org/10.6028/NIST.AI.100-1 January 2023 U.S. Department of Commerce Gina M. Raimondo, Secretary National Institute of Standards and Technology Laurie E. Locascio, NIST Director and Under Secretary of Commerce for Standards and Technology', 'kb-doc-12-nist-ai-rmf-p2-1', 0, 50, '12-nist-ai-rmf', 'retrieved', 'DF14390F145CE04C8CAFD2188FCBB226EA08D17C9532961F0A973E0482DCF95D', 'v1', '{"source_id": "12-nist-ai-rmf", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
