VALUES ('doc-13-nist-genai-profile-p2-5', 'doc-13-nist-genai-profile', '', 2, 'U.S. Department of Commerce Gina M. Raimondo, Secretary National Institute of Standards and Technology Laurie E. Locascio, NIST Director and Under Secretary of Commerce for Standards and Technology', 'kb-doc-13-nist-genai-profile-p2-5', 0, 28, '13-nist-genai-profile', 'retrieved', '34BE38008CD040607D79719774E448DB8ABCE929E214F3EE6D15FBB5EF0C8F0D', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
