INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-13-nist-genai-profile-p3-2', 'doc-13-nist-genai-profile', '', 3, 'About AI at NIST: The National Institute of Standards and Technology (NIST) develops measurements, technology, tools, and standards to advance reliable, safe, transparent, explainable, privacy-enhanced, and fair artiﬁcial intelligence (AI) so that its full commercial and societal beneﬁts can be realized without harm to people or the planet. NIST, which has conducted both fundamental and applied work on AI for more than a decade, is also helping to fulﬁll the 2023 Executive Order on Safe, Secure, and Trustworthy AI. NIST established the U.S. AI Safety Institute and the companion AI Safety Institute Consortium to continue the eﬀorts set in motion by the E.O. to build the science necessary for safe, secure, and trustworthy development and use of AI.', 'kb-doc-13-nist-genai-profile-p3-2', 0, 118, '13-nist-genai-profile', 'retrieved', '0CB1B7F11D732E4648566A27E093EA14CF7707F287C0BC124B1C7D7CEAF52233', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-13-nist-genai-profile-p3-3', 'doc-13-nist-genai-profile', '', 3, 'Acknowledgments: This report was accomplished with the many helpful comments and contributions from the community, including the NIST Generative AI Public Working Group, and NIST staﬀ and guest researchers: Chloe Autio, Jesse Dunietz, Patrick Hall, Shomik Jain, Kamie Roberts, Reva Schwartz, Martin Stanley, and Elham Tabassi.', 'kb-doc-13-nist-genai-profile-p3-3', 0, 46, '13-nist-genai-profile', 'retrieved', '717070798481A0C9021496BB0F7FBF5FEDA6F432226B6C4B628FC13C7DEBF006', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
