VALUES ('doc-13-nist-genai-profile-p16-4', 'doc-13-nist-genai-profile', '', 16, 'For example, test datasets commonly used to benchmark or validate models can contain label errors.', 'kb-doc-13-nist-genai-profile-p16-4', 0, 15, '13-nist-genai-profile', 'retrieved', '9899AAF55615AE8E44C8695EE175473172244FD609E05E08AF40D9E7C515A205', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
