INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-13-nist-genai-profile-p16-7', 'doc-13-nist-genai-profile', '', 16, 'In addition to the suggested actions below, AI risk management activities and actions set forth in the AI RMF 1.0 and Playbook are already applicable for managing GAI risks. Organizations are encouraged to apply the activities suggested in the AI RMF and its Playbook when managing the risk of GAI systems.', 'kb-doc-13-nist-genai-profile-p16-7', 0, 51, '13-nist-genai-profile', 'retrieved', '12AE20C33B129A5EA5F05FDC8CF3B0894280052727A4709642E70F750EA0DC63', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
