INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-13-nist-genai-profile-p16-8', 'doc-13-nist-genai-profile', '', 16, 'Implementation of the suggested actions will vary depending on the type of risk, characteristics of GAI systems, stage of the GAI lifecycle, and relevant AI actors involved.', 'kb-doc-13-nist-genai-profile-p16-8', 0, 27, '13-nist-genai-profile', 'retrieved', 'E1428C1102F895157D94244CB2A2227A811934C5E6B4A9A3CA388C5EDBA852E5', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
