VALUES ('doc-13-nist-genai-profile-p16-10', 'doc-13-nist-genai-profile', '', 16, '• Not every subcategory of the AI RMF is included in this document.13 Suggested actions are listed for only some subcategories.', 'kb-doc-13-nist-genai-profile-p16-10', 0, 21, '13-nist-genai-profile', 'retrieved', '63BDE6E10B6B775CEED36F787F43215BC08BD47F11F00D5733D8F412B8E89155', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
