INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-13-nist-genai-profile-p27-2', 'doc-13-nist-genai-profile', '', 27, 'Harmful Bias and Homogenization MP-1.1-003 Document risk measurement plans to address identiﬁed risks. Plans may include, as applicable: Individual and group cognitive biases (e.g., conﬁrmation bias, funding bias, groupthink) for AI Actors involved in the design, implementation, and use of GAI systems; Known past GAI system incidents and failure modes; In-context use and foreseeable misuse, abuse, and oﬀ-label use; Over reliance on quantitative metrics and methodologies without suﬃcient awareness of their limitations in the context(s) of use; Standard measurement and structured human feedback approaches; Anticipated human-AI conﬁgurations.', 'kb-doc-13-nist-genai-profile-p27-2', 0, 87, '13-nist-genai-profile', 'retrieved', 'E7621119795F9E6FD4F4A4A33C382EAB21232543263D8A7908A5B0BBF668B8EF', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
