VALUES ('doc-13-nist-genai-profile-p49-8', 'doc-13-nist-genai-profile', '', 49, 'Information Security MG-4.3-002 Establish and maintain policies and procedures to record and track GAI system reported errors, near-misses, and negative impacts.', 'kb-doc-13-nist-genai-profile-p49-8', 0, 21, '13-nist-genai-profile', 'retrieved', '297BB72A534E19E073288411B6DBC0B680E742FAD383680B77D529A9BE3A3B54', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
