VALUES ('doc-13-nist-genai-profile-p50-1', 'doc-13-nist-genai-profile', '', 50, '46 MG-4.3-003 Report GAI incidents in compliance with legal and regulatory requirements (e.g., HIPAA breach reporting, e.g., OCR (2023) or NHTSA (2022) autonomous vehicle crash reporting requirements.', 'kb-doc-13-nist-genai-profile-p50-1', 0, 27, '13-nist-genai-profile', 'retrieved', 'B1B604A8F3A14C741A6B898D91C1773D984EDCF230429FC5A59DF83CC1344577', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
