VALUES ('doc-13-nist-genai-profile-p50-2', 'doc-13-nist-genai-profile', '', 50, 'Information Security; Data Privacy AI Actor Tasks: AI Deployment, Aﬀected Individuals and Communities, Domain Experts, End-Users, Human Factors, Operation and Monitoring', 'kb-doc-13-nist-genai-profile-p50-2', 0, 21, '13-nist-genai-profile', 'retrieved', '5E7505583807FE72AF9A40B8D8EA68D9134714A39430F68B6ECC9AB41398FC7F', 'v1', '{"source_id": "13-nist-genai-profile", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
